window.RPH_DATA = {"tahun": 5, "mataPelajaran": "Sains", "sesi": 2026, "kurikulum": "KSSR Semakan", "sekolah": "SK Kuala Betis", "entries": [{"id": 1, "title": "Aktiviti Minggu Pertama Persekolahan", "minggu": 1, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Inkuiri dalam Sains", "topik": "Aktiviti Minggu Pertama Persekolahan", "standardKandungan": "Pengenalan Pengurusan Bilik Sains dan Kemahiran Saintifik", "standardPembelajaran": "Aktiviti Pengenalan, Suasana Persekolahan Baharu, Suai Kenal Bilik Sains & Peraturan Bilik Sains", "objektifPembelajaran": "Di akhir pengajaran, murid dapat menyatakan sekurang-kurangnya 5 Peraturan Bilik Sains dengan betul dan melakonkan cara menjaga keselamatan di dalam Bilik Sains.", "kriteriaKejayaan": "(1) Murid boleh menyatakan semula peraturan Bilik Sains secara bertulis atau lisan. (2) Murid boleh mengenal pasti tindakan yang betul semasa berlaku kecemasan di Bilik Sains.", "setInduksi": "Guru menyambut kedatangan murid dengan senyuman dan memainkan lagu ceria \"Sains Itu Seronok\". Guru menunjukkan gambar kartun Bilik Sains yang tunggang-langgang untuk mencetuskan perbincangan awal (5 minit).", "penyampaian": ["Aktiviti Suai Kenal: Murid dan guru memperkenalkan diri secara kreatif menggunakan permainan \"Bola Pas\".", "Guru membimbing murid melawat Bilik Sains dan memperkenalkan sudut-sudut pembelajaran, peralatan sains utama, serta tempat penyimpanan bahan kitar semula.", "Murid melaksanakan Aktiviti Ria: Kenali Bilik Sains Kita (Rujukan Buku Teks m/s v-vi). Murid dibahagikan kepada kumpulan kecil untuk meneroka sudut makmal.", "Sesi sumbang saran: Murid membincangkan akibat jika tidak mematuhi Peraturan Bilik Sains.", "Setiap kumpulan membentangkan satu senario peraturan Bilik Sains menggunakan kad situasi."], "penutup": "Murid membuat rumusan kognitif dengan menyebut \"Sains adalah kehidupan saya\" secara beramai-ramai dan melengkapkan ikrar penjagaan Bilik Sains.", "pentaksiran": "Pemerhatian sikap saintifik dan pembentangan kad situasi.", "bahanBantuBelajar": "Pembesar suara, lagu sains, kad situasi peraturan, gambar Bilik Sains tunggang-langgang.", "refleksi": ""}, {"id": 2, "title": "Aktiviti Minggu Pertama Persekolahan", "minggu": 1, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Inkuiri dalam Sains", "topik": "Aktiviti Minggu Pertama Persekolahan", "standardKandungan": "Pengenalan Kemahiran Proses Sains (KPS)", "standardPembelajaran": "Aktiviti Pengenalan Kemahiran Saintifik secara santai melalui permainan dan inkuiri ringkas.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat menyenaraikan sekurang-kurangnya 3 Kemahiran Proses Sains (KPS) yang digunakan semasa menjalankan permainan inkuiri ringkas.", "kriteriaKejayaan": "(1) Murid boleh membezakan antara pemerhatian dan inferens berdasarkan situasi permainan. (2) Murid boleh berkomunikasi secara lisan untuk menerangkan hasil aktiviti ringkas.", "setInduksi": "Guru menunjukkan sebuah kotak hitam misteri yang mengeluarkan bunyi apabila digoncang. Murid diminta meneka isi kotak tersebut (5 minit).", "penyampaian": ["Murid diterangkan secara ringkas tentang 12 Kemahiran Proses Sains (KPS) yang bakal dipelajari sepanjang Tahun 5 (Rujukan Buku Teks m/s 15).", "Murid menjalankan aktiviti inkuiri ringkas menggunakan kotak misteri. Murid mencatat pemerhatian kualitatif (bunyi, berat kotak) menggunakan panca indera mereka tanpa membuka kotak.", "Murid digalakkan untuk membina inferens awal berdasarkan maklumat tersebut.", "Guru membuka kotak dan menunjukkan isi sebenar (contoh: beberapa biji guli). Murid membandingkan ramalan asal dengan jawapan sebenar.", "Murid merujuk halaman rangsangan Buku Teks Unit 1 (m/s 1) untuk membincangkan senario \"Tarik Upih\" dan mengenal pasti KPS yang terlibat seperti memerhati dan membuat inferens."], "penutup": "Guru merumuskan kepentingan KPS dalam membantu menyelesaikan masalah harian secara saintifik.", "pentaksiran": "Lisan, soal jawab, dan catatan pemerhatian kotak misteri.", "bahanBantuBelajar": "Kotak hitam misteri, guli, Buku Teks Sains Tahun 5 SK.", "refleksi": ""}, {"id": 3, "title": "Unit 1: Kemahiran Saintifik", "minggu": 2, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Inkuiri dalam Sains", "topik": "Unit 1: Kemahiran Saintifik", "standardKandungan": "1.1 Kemahiran Proses Sains", "standardPembelajaran": "1.1.1 Memerhati dengan menggunakan semua deria yang terlibat dan alat jika perlu untuk membuat pemerhatian secara kualitatif bagi menerangkan fenomena atau perubahan yang berlaku.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat membuat sekurang-kurangnya 4 pemerhatian kualitatif tentang ciri-ciri fizikal kapal terbang kertas yang dihasilkan menggunakan semua panca indera yang terlibat dengan betul.", "kriteriaKejayaan": "(1) Murid boleh menyatakan ciri fizikal objek berdasarkan warna, bentuk, saiz, dan tekstur permukaan kertas. (2) Murid boleh menyenaraikan deria yang digunakan untuk setiap pemerhatian.", "setInduksi": "Guru menunjukkan sehelai kertas berwarna yang diedarkan untuk pertandingan (Buku Teks m/s 2). Guru bertanyakan soalan rangsangan tentang sifat fizikal kertas tersebut (5 minit).", "penyampaian": ["Murid meneliti teks rangsangan pertandingan melipat kapal terbang kertas Tahun 5 Zamrud (Buku Teks m/s 2).", "Murid menghasilkan kapal terbang kertas masing-masing mengikut kaedah melipat yang dipilih (Contoh: \"Cara Ana melipat kapal terbang kertasnya\" Buku Teks m/s 3).", "Murid membuat pemerhatian kualitatif ke atas kapal terbang kertas mereka sendiri dan mencatatkan pemerhatian tersebut.", "Murid menyentuh hujung tirus kapal terbang, melihat saiz sayap, merasai tekstur licin/kasar kertas, dan membentangkan ciri fizikalnya secara berpasangan."], "penutup": "Guru membimbing murid merumuskan bahawa pemerhatian kualitatif tidak menggunakan nombor sebaliknya menggunakan panca indera penglihatan, sentuhan, pendengaran, bau, dan rasa.", "pentaksiran": "Lembaran kerja pemerhatian ciri fizikal kapal terbang kertas.", "bahanBantuBelajar": "Kertas berwarna (pelbagai saiz dan warna), Buku Teks Sains Tahun 5 m/s 2-3.", "refleksi": ""}, {"id": 4, "title": "Unit 1: Kemahiran Saintifik", "minggu": 2, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Inkuiri dalam Sains", "topik": "Unit 1: Kemahiran Saintifik", "standardKandungan": "1.1 Kemahiran Proses Sains", "standardPembelajaran": "1.1.1 Memerhati dengan menggunakan semua deria yang terlibat dan alat jika perlu untuk membuat pemerhatian secara kualitatif bagi menerangkan fenomena atau perubahan yang berlaku.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat membandingkan 2 bentuk kapal terbang kertas yang tirus dan lebar untuk menerangkan kesan daya rintangan angin berdasarkan pemerhatian dengan tepat.", "kriteriaKejayaan": "(1) Murid boleh melukis perbezaan bentuk bahagian hadapan kapal terbang kertas Ana (panjang dan runcing) dengan Ravi (sayap lebar). (2) Murid boleh mengaitkan bentuk runcing dengan pengurangan daya rintangan angin secara lisan.", "setInduksi": "Guru melancarkan satu kapal terbang kertas bermuncung runcing dan satu kapal terbang kertas bermuncung rata ke udara, murid memerhatikan perbezaan cara kedua-duanya terbang (5 minit).", "penyampaian": ["Murid merujuk perbincangan Ana dan Melia tentang bentuk hadapan kapal terbang yang tirus dan runcing (Buku Teks m/s 2-4).", "Murid melipat kapal terbang kertas mengikut \"Cara Ravi melipat kapal terbang kertasnya\" (Buku Teks m/s 4) untuk mendapatkan bentuk sayap yang lebih besar dan hujung tirus.", "Murid berpasangan menguji terbang uji kapal terbang runcing (Ana) dan kapal terbang bersayap besar (Ravi).", "Murid mencatatkan pemerhatian tentang kestabilan penerbangan kedua-dua model tersebut."], "penutup": "Murid merumuskan pemerhatian mereka bahawa bentuk tirus menambah kestabilan dan membolehkan model terbang lebih jauh.", "pentaksiran": "Pembentangan lisan murid tentang kesan kestabilan bentuk kapal terbang.", "bahanBantuBelajar": "Kertas berwarna, Buku Teks m/s 2-4.", "refleksi": ""}, {"id": 5, "title": "Unit 1: Kemahiran Saintifik", "minggu": 3, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Inkuiri dalam Sains", "topik": "Unit 1: Kemahiran Saintifik", "standardKandungan": "1.1 Kemahiran Proses Sains", "standardPembelajaran": "1.1.2 Mengelas dengan membandingkan atau mengenal pasti persamaan dan perbezaan berdasarkan ciri sepunya.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat mengelaskan sekurang-kurangnya 6 jenis model kapal terbang kertas ke dalam jadual pengelasan berdasarkan ciri saiz sayap atau bentuk muncung dengan betul.", "kriteriaKejayaan": "(1) Murid boleh mengenal pasti persamaan dan perbezaan antara model kapal terbang kertas rakan-rakan. (2) Murid boleh melengkapkan carta pengelasan grafik dengan kemas.", "setInduksi": "Guru mengumpulkan semua kapal terbang kertas murid di atas meja hadapan dan bertanyakan bagaimana cara menyusun semua model ini supaya lebih kemas dan teratur (5 minit).", "penyampaian": ["Murid mengimbas kembali perbincangan tentang pelbagai bentuk kapal terbang kertas dalam dewan tertutup (Buku Teks m/s 5).", "Murid berbincang dalam kumpulan untuk menyusun model-model tersebut mengikut satu ciri sepunya (Contoh: Kumpulan model bersayap besar vs Kumpulan model bersayap kecil).", "Murid membina jadual pengelasan di atas kertas mahjung menggunakan pen penanda (Aktiviti pengelasan, Buku Teks m/s 5).", "Setiap kumpulan melakukan \"Gallery Walk\" untuk melihat cara kumpulan lain mengelas objek."], "penutup": "Murid merumuskan maksud mengelas iaitu mengelompokkan objek berdasarkan ciri persamaan dan perbezaan yang dikenal pasti.", "pentaksiran": "Lembaran kerja pengelasan ciri sepunya.", "bahanBantuBelajar": "Model-model kapal terbang kertas murid, kertas mahjung, pen penanda.", "refleksi": ""}, {"id": 6, "title": "Unit 1: Kemahiran Saintifik", "minggu": 3, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Inkuiri dalam Sains", "topik": "Unit 1: Kemahiran Saintifik", "standardKandungan": "1.1 Kemahiran Proses Sains", "standardPembelajaran": "1.1.3 Mengukur dan menggunakan nombor dengan menggunakan alat dan unit piawai dengan teknik yang betul.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat mengukur panjang bentangan sayap kapal terbang kertas menggunakan pita pengukur atau pembaris dalam unit sentimeter (cm) dengan teknik pembacaan skala yang tepat.", "kriteriaKejayaan": "(1) Murid boleh meletakkan kedudukan angka '0' pembaris pada pangkal sayap dengan betul. (2) Murid boleh menulis ukuran panjang sayap beserta unit piawai sentimeter (cm).", "setInduksi": "Guru menunjukkan pembaris kayu dan bertanyakan bagaimana cara mengukur saiz sayap kapal terbang kertas dengan tepat tanpa mengagak (5 minit).", "penyampaian": ["Guru menerangkan teknik mengukur yang betul: meletakkan hujung objek pada tanda sifar (0) dan menyelaraskan kedudukan mata secara tegak di atas skala pembaris.", "Murid melatih mengukur bentangan sayap kapal terbang masing-masing (Buku Teks m/s 3-4, rujukan langkah lipatan).", "Murid menjalankan aktiviti mencatatkan panjang sayap (cm) dan berat model (g) jika menggunakan penimbang digital.", "Setiap kumpulan membandingkan ukuran sayap model ahli masing-masing dan mencatatkannya ke dalam buku nota."], "penutup": "Murid merumuskan kepentingan menggunakan alat piawai untuk mengelakkan ralat dalam sains.", "pentaksiran": "Amali menyukat panjang menggunakan pembaris piawai.", "bahanBantuBelajar": "Pembaris sentimeter, model kapal terbang kertas, buku nota.", "refleksi": ""}, {"id": 7, "title": "Unit 1: Kemahiran Saintifik", "minggu": 4, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Inkuiri dalam Sains", "topik": "Unit 1: Kemahiran Saintifik", "standardKandungan": "1.1 Kemahiran Proses Sains", "standardPembelajaran": "1.1.4 Membuat inferens dengan menyatakan kesimpulan awal atau penerangan yang munasabah bagi sesuatu pemerhatian dengan menggunakan maklumat yang diperoleh.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat memberikan sekurang-kurangnya 2 inferens (sebab) yang munasabah tentang perbezaan jarak terbang kapal terbang kertas berdasarkan pemerhatian awal.", "kriteriaKejayaan": "(1) Murid boleh menulis inferens menggunakan format hubungan \"kerana...\". (2) Murid boleh menghubungkaitkan bentuk muncung kapal terbang dengan kelajuan terbangnya.", "setInduksi": "Guru mempamerkan dua keputusan penerbangan: Kapal Terbang A terbang sejauh 5 meter, Kapal Terbang B terbang sejauh 2 meter. Guru bertanya: \"Mengapakah perkara ini berlaku?\" (5 minit).", "penyampaian": ["Murid meneliti semula kisah dewan tertutup (Buku Teks m/s 5-6).", "Guru menerangkan maksud inferens sebagai penerangan saintifik bagi sesuatu pemerhatian berdasarkan pengetahuan sedia ada.", "Murid membuat uji cuba penerbangan kapal terbang kertas mereka dalam kumpulan di kawasan dewan tertutup.", "Murid mencatatkan pemerhatian: \"Kapal terbang Ana terbang lebih jauh daripada kapal terbang Melia.\"", "Murid membina inferens: \"Kapal terbang Ana terbang lebih jauh kerana bentuk muncungnya yang tirus mengurangkan daya rintangan angin.\""], "penutup": "Guru menegaskan bahawa sesuatu inferens perlulah disusuli dengan bukti penyiasatan lanjut.", "pentaksiran": "Lembaran kerja membina inferens saintifik.", "bahanBantuBelajar": "Model kapal terbang kertas, Buku Teks m/s 5-6.", "refleksi": ""}, {"id": 8, "title": "Unit 1: Kemahiran Saintifik", "minggu": 4, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Inkuiri dalam Sains", "topik": "Unit 1: Kemahiran Saintifik", "standardKandungan": "1.1 Kemahiran Proses Sains", "standardPembelajaran": "1.1.5 Meramal dengan membuat jangkaan tentang sesuatu peristiwa atau fenomena berdasarkan pemerhatian, pengalaman lalu atau data.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat meramalkan jarak penerbangan kapal terbang kertas apabila parameter panjang penarikan gelang getah diubah berdasarkan trend data sedia ada.", "kriteriaKejayaan": "(1) Murid boleh membuat jangkaan jarak terbang (cm) bagi penarikan gelang getah sejauh 40 cm berdasarkan trend data 10 cm, 20 cm, dan 30 cm. (2) Murid boleh membina ramalan logik berdasarkan pengalaman lalu.", "setInduksi": "Guru melastik seutas gelang getah pendek dan seutas gelang getah yang ditarik panjang. Murid meramal getah mana yang akan pergi lebih jauh (5 minit).", "penyampaian": ["Murid merujuk kepada rancangan eksperimen \"Aktiviti Kumpulan: Jarak Terbang Kapal Terbang Kertas\" (Buku Teks m/s 6).", "Murid membina jangkaan (ramalan) tentang jarak terbang sebelum melancarkan kapal terbang kertas menggunakan klip kertas dan gelang getah.", "Murid melihat corak data: jika gelang getah ditarik 10 cm menghasilkan jarak 150 cm, ditarik 20 cm menghasilkan 300 cm, murid meramal jarak bagi tarikan 30 cm (jangkaan: sekitar 450 cm).", "Murid berbincang secara berkumpulan untuk meramalkan apa yang terjadi sekiranya eksperimen dijalankan di luar dewan yang berangin kencang."], "penutup": "Murid membuat perkaitan bahawa ramalan bukan tekaan rawak, tetapi jangkaan saintifik berdasarkan corak data terdahulu.", "pentaksiran": "Lembaran kerja meramal jarak penerbangan.", "bahanBantuBelajar": "Gelang getah, klip kertas, stapler, pita pengukur, Buku Teks m/s 6-7.", "refleksi": ""}, {"id": 9, "title": "Unit 1: Kemahiran Saintifik", "minggu": 5, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Inkuiri dalam Sains", "topik": "Unit 1: Kemahiran Saintifik", "standardKandungan": "1.1 Kemahiran Proses Sains", "standardPembelajaran": "1.1.6 Berkomunikasi dengan merekod maklumat atau idea dalam bentuk yang sesuai dan mempersembahkan maklumat atau idea tersebut secara sistematik.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat merekodkan data jarak penerbangan kapal terbang kertas ke dalam jadual struktur data yang lengkap dan mempersembahkannya secara lisan dengan kemas.", "kriteriaKejayaan": "(1) Murid boleh melengkapkan jadual dua lajur (Panjang Gelang Getah vs Jarak Terbang) dengan tajuk lajur dan unit piawai yang betul. (2) Murid boleh menerangkan hasil jadual di hadapan kelas secara sistematik.", "setInduksi": "Guru menunjukkan sekeping kertas yang penuh dengan coretan nombor jarak terbang yang bersepah dan bertanya: \"Adakah data ini mudah dibaca?\" (5 minit).", "penyampaian": ["Murid menjalankan aktiviti melancarkan kapal terbang menggunakan pelancar gelang getah mengikut rujukan langkah 1 hingga 7 dalam Eksperimen Jarak Terbang (Buku Teks m/s 6-7).", "Murid mengumpul data jarak terbang bagi tarikan 10 cm, 20 cm, dan 30 cm.", "Setiap kumpulan merekodkan data tersebut ke dalam jadual (Rujukan Buku Teks m/s 7).", "Murid menukar bentuk jadual tersebut kepada bentuk carta palang ringkas di atas kertas graf.", "Setiap kumpulan membentangkan hasil graf tersebut di hadapan kelas."], "penutup": "Murid merumuskan bahawa komunikasi yang berkesan dalam sains boleh dilakukan melalui jadual, graf, dan lukisan rajah bersimbol.", "pentaksiran": "Hasil kerja membina jadual data dan carta palang.", "bahanBantuBelajar": "Kertas graf, pembaris, data eksperimen, Buku Teks m/s 7.", "refleksi": ""}, {"id": 10, "title": "Unit 1: Kemahiran Saintifik", "minggu": 5, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Inkuiri dalam Sains", "topik": "Unit 1: Kemahiran Saintifik", "standardKandungan": "1.1 Kemahiran Proses Sains", "standardPembelajaran": "1.1.7 Menggunakan perhubungan ruang dan masa dengan menyusun kejadian sesuatu fenomena atau peristiwa mengikut kronologi berdasarkan masa.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat menjelaskan perkaitan perubahan kedudukan dan saiz buih sabun dengan bertambahnya masa semasa ditiup dengan betul.", "kriteriaKejayaan": "(1) Murid boleh menerangkan hubungan: \"Semakin bertambah saiz buih sabun, semakin bertambah tempoh masa ketahanannya\". (2) Murid boleh menyusun kronologi pembentukan buih sabun dari peringkat mula ditiup sehingga pecah.", "setInduksi": "Guru meniup sebiji belon secara perlahan-lahan. Murid memerhatikan perubahan saiz belon mengikut masa peniupan (5 minit).", "penyampaian": ["Murid membaca perbincangan tentang perkaitan ruang dan masa bagi kestabilan buih sabun (Buku Teks m/s 12).", "Murid menjalankan aktiviti meniup buih sabun gergasi secara perlahan-lahan menggunakan penyedut minuman (Rujukan Buku Teks m/s 11-12).", "Murid mencatatkan perubahan saiz buih sabun (ruang) pada selang masa setiap 2 saat (masa).", "Murid menyusun urutan gambar kronologi pembentukan buih sabun dari fasa cecair, mula kembung, mengembang gergasi, dan saat pecah."], "penutup": "Guru membimbing murid merumuskan konsep perhubungan ruang dan masa: bagaimana parameter fizikal (saiz, isipadu, bentuk) berubah apabila masa bertambah.", "pentaksiran": "Lembaran kerja urutan kronologi perubahan fizikal objek mengikut masa.", "bahanBantuBelajar": "Larutan sabun, penyedut minuman, jam randik, kad gambar kronologi buih.", "refleksi": ""}, {"id": 11, "title": "Unit 1: Kemahiran Saintifik", "minggu": 6, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Inkuiri dalam Sains", "topik": "Unit 1: Kemahiran Saintifik", "standardKandungan": "1.1 Kemahiran Proses Sains", "standardPembelajaran": "1.1.8 Mentafsir data dengan memilih idea yang relevan tentang objek, peristiwa atau pola yang terdapat pada data untuk membuat penerangan.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat menterjemah maklumat dari graf atau jadual eksperimen buih sabun untuk menentukan kuantiti gliserin yang paling optimum bagi ketahanan buih sabun dengan tepat.", "kriteriaKejayaan": "(1) Murid boleh membaca jadual eksperimen dan mengenal pasti pola perubahan masa (meningkat/menurun). (2) Murid boleh membuat satu kenyataan bertulis untuk menerangkan trend data.", "setInduksi": "Guru mempamerkan graf garis trend peningkatan ketahanan buih sabun berdasarkan kuantiti gliserin yang ditambah (5 minit).", "penyampaian": ["Murid merujuk jadual keputusan eksperimen larutan sabun bercampur gliserin (Buku Teks m/s 11-12).", "Murid menganalisis data: Larutan dengan 1 sudu gliserin bertahan 45 saat, 3 sudu bertahan 120 saat, dan 5 sudu bertahan 143 saat (Rujukan Buku Teks m/s 11-12).", "Murid membincangkan soalan: \"Berapakah sudu besar gliserin yang diperlukan untuk menghasilkan buih sabun paling lambat pecah?\" (Mentafsir Data, Buku Teks m/s 11-12).", "Setiap kumpulan merumuskan pola: \"Apabila kuantiti gliserin bertambah, tempoh ketahanan buih sabun bertambah.\""], "penutup": "Murid membuat pembentangan ringkas tentang tafsiran graf garisan ketahanan buih sabun.", "pentaksiran": "Lembaran kerja mentafsir data jadual/graf.", "bahanBantuBelajar": "Buku Teks m/s 11-12, lembaran graf garisan, kad aktiviti tafsiran.", "refleksi": ""}, {"id": 12, "title": "Unit 1: Kemahiran Saintifik", "minggu": 6, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Inkuiri dalam Sains", "topik": "Unit 1: Kemahiran Saintifik", "standardKandungan": "1.1 Kemahiran Proses Sains", "standardPembelajaran": "1.1.9 Mendefinisi secara operasi dengan memerihalkan satu tafsiran tentang perkara yang dilakukan dan diperhatikan bagi sesuatu situasi mengikut aspek yang ditentukan.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat menulis satu definisi secara operasi bagi \"tempoh ketahanan buih sabun\" berdasarkan perkara yang dilakukan dan diperhatikan dalam eksperimen dengan tepat.", "kriteriaKejayaan": "(1) Murid boleh menyatakan definisi secara operasi dengan merujuk kepada tindakan (meniup buih) dan pemerhatian (tempoh masa sebelum buih pecah). (2) Murid boleh membezakan antara definisi teori dengan definisi secara operasi.", "setInduksi": "Guru bertanya: \"Bagaimanakah kita tahu buih sabun itu stabil dan kuat?\" Murid memberi pelbagai jawapan teoritis (5 minit).", "penyampaian": ["Guru menerangkan konsep Definisi Secara Operasi (DSO): mentakrifkan sesuatu pemboleh ubah dengan menyatakan tindakan fizikal dan pemerhatian yang boleh diukur.", "Murid merujuk perbincangan Ana dan rakan-rakan tentang cara mendefinisi secara operasi ketahanan buih sabun (Buku Teks m/s 12-13).", "Murid melatih menulis DSO: \"Ketahanan buih sabun ialah tempoh masa yang dicatatkan oleh jam randik bermula dari tiupan buih selesai sehingga buih itu pecah.\"", "Murid membina satu lagi DSO bagi \"jaruk terbang kapal terbang kertas\" (Rujukan Buku Teks m/s 7)."], "penutup": "Guru mengukuhkan kefahaman murid bahawa DSO membantu saintis mengukur pemboleh ubah yang abstrak secara konkrit.", "pentaksiran": "Aktiviti bertulis menulis rumusan Definisi Secara Operasi.", "bahanBantuBelajar": "Kad formula DSO, Buku Teks m/s 12-13.", "refleksi": ""}, {"id": 13, "title": "Unit 1: Kemahiran Saintifik", "minggu": 7, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Inkuiri dalam Sains", "topik": "Unit 1: Kemahiran Saintifik", "standardKandungan": "1.1 Kemahiran Proses Sains", "standardPembelajaran": "1.1.10 Mengawal pemboleh ubah dengan menentukan pemboleh ubah bergerak balas dan dimalarkan setelah pemboleh ubah dimanipulasi ditentukan dalam sesuatu penyiasatan.; 1.1.11 Membuat hipotesis dengan membuat pernyataan umum yang boleh diuji tentang hubungan antara pemboleh ubah dalam sesuatu penyiasatan.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat mengenal pasti tiga jenis pemboleh ubah (PM, PB, PD) bagi eksperimen ketahanan buih sabun dan merumuskan satu hipotesis yang boleh diuji dengan betul.", "kriteriaKejayaan": "(1) Murid boleh menyenaraikan PM (kuantiti gliserin), PB (tempoh ketahanan buih), dan PD (jenis sabun, isipadu air). (2) Murid boleh menulis hipotesis: \"Semakin bertambah kuantiti gliserin, semakin bertambah tempoh ketahanan buih sabun\".", "setInduksi": "Guru menunjukkan dua botol larutan sabun yang sama isipadu tetapi satu daripadanya mengandungi gliserin. Guru mencetuskan perbincangan pemboleh ubah (5 minit).", "penyampaian": ["Murid meneliti teks penyataan masalah dan pemboleh ubah eksperimen buih sabun (Buku Teks m/s 8-9).", "Guru menerangkan kaedah mengenal pasti Pemboleh Ubah Dimanipulasikan (PM), Pemboleh Ubah Bergerak Balas (PB), dan Pemboleh Ubah Dimalarkan (PD).", "Murid bekerja dalam kumpulan membincangkan cara mengekalkan keadilan eksperimen dengan menyenaraikan PD secara terperinci (jenis cecair pencuci, isipadu air, saiz buih, kelajuan angin).", "Murid membina draf hipotesis berdasarkan ramalan awal Ana (Buku Teks m/s 9)."], "penutup": "Setiap kumpulan membacakan hipotesis mereka dan guru membetulkan struktur ayat hipotesis.", "pentaksiran": "Lembaran kerja mengenal pasti pemboleh ubah dan pembinaan hipotesis.", "bahanBantuBelajar": "Slaid penerangan pemboleh ubah, kad perbincangan PM/PB/PD.", "refleksi": ""}, {"id": 14, "title": "Unit 1: Kemahiran Saintifik", "minggu": 7, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Inkuiri dalam Sains", "topik": "Unit 1: Kemahiran Saintifik", "standardKandungan": "1.1 Kemahiran Proses Sains", "standardPembelajaran": "1.1.12 Mengeksperimen dengan menggunakan kemahiran proses sains asas bagi mengumpul dan mentafsir data serta membuat rumusan untuk membuktikan hipotesis dan membuat laporan.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat menjalankan langkah-langkah eksperimen ketahanan buih sabun secara sistematik dan selamat untuk membuktikan hipotesis yang dibina.", "kriteriaKejayaan": "(1) Murid boleh mengikut prosedur penyediaan larutan sabun dengan gliserin (1, 3, dan 5 sudu besar) mengikut Buku Teks m/s 10-11. (2) Murid boleh melengkapkan laporan eksperimen dengan kesimpulan yang tepat.", "setInduksi": "Guru memberi taklimat keselamatan penggunaan gogal dan amaran lantai licin sebelum memulakan eksperimen (5 minit).", "penyampaian": ["Murid memakai gogal keselamatan dan berkumpul mengikut kumpulan masing-masing di kawasan kurang berangin (Buku Teks m/s 10).", "Murid menyediakan radas: bekas plastik, silinder penyukat, jam randik, cecair pencuci, dan gliserin (Rujukan Buku Teks m/s 10-11).", "Murid menjalankan eksperimen mengikut turutan langkah (a) hingga (i) dalam Buku Teks m/s 10-11.", "Murid merekod masa pecah buih ke dalam jadual (Rujukan Buku Teks m/s 11).", "Murid menganalisis data, menulis kesimpulan \"Hipotesis Diterima\", dan menyediakan laporan lengkap."], "penutup": "Murid membincangkan rancangan keusahawanan untuk menjual cecair buih sabun gergasi ini semasa Minggu Keusahawanan sekolah (Buku Teks m/s 13).", "pentaksiran": "Penilaian laporan eksperimen \"Ketahanan Buih Sabun\" (PBD KPS).", "bahanBantuBelajar": "Gogal, silinder penyukat, jam randik, gliserin, cecair pencuci pinggan, bekas plastik.", "refleksi": ""}, {"id": 15, "title": "Unit 2: Manusia", "minggu": 8, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "Unit 2: Manusia", "standardKandungan": "2.1 Sistem Rangka Manusia", "standardPembelajaran": "2.1.1 Memerihalkan fungsi rangka utama manusia.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat menamakan dan memerihalkan fungsi 4 rangka utama manusia (tengkorak, tulang belakang, tulang rusuk, tulang tangan & kaki) dengan tepat.", "kriteriaKejayaan": "(1) Murid boleh memadankan bahagian rangka utama dengan organ penting yang dilindunginya. (2) Murid boleh menyatakan fungsi tulang belakang sebagai penyokong tubuh.", "setInduksi": "Guru menunjukkan gambar imbasan sinar-X kaki yang cedera (Buku Teks m/s 19) dan mencetuskan perbincangan tentang struktur keras di dalam badan manusia (5 minit).", "penyampaian": ["Murid membaca teks dialog perbandingan cacing yang menjalar dengan manusia yang boleh berdiri tegak (Buku Teks m/s 20).", "Murid meneliti rajah Sistem Rangka Manusia (Buku Teks m/s 20-21).", "Sesi sumbang saran: Murid membincangkan fungsi:", "Murid melukis lakaran ringkas sistem rangka manusia dan melabelkan nama serta fungsinya."], "penutup": "Murid membuat rumusan kognitif tentang peranan rangka utama sebagai pelindung dan sokongan mekanikal tubuh.", "pentaksiran": "Kuiz suai padan fungsi rangka utama.", "bahanBantuBelajar": "Model rangka manusia, slaid imbasan sinar-X, gambar rajah sistem rangka.", "refleksi": ""}, {"id": 16, "title": "Unit 2: Manusia", "minggu": 8, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "Unit 2: Manusia", "standardKandungan": "2.1 Sistem Rangka Manusia", "standardPembelajaran": "2.1.2 Mengenal pasti tulang dan kedudukan sendi dalam sistem rangka manusia.; 2.1.3 Menyatakan fungsi sendi dalam sistem rangka manusia.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat membulatkan sekurang-kurangnya 5 kedudukan sendi pada rajah rangka manusia dan menerangkan peranan sendi dalam memudahkan pergerakan tubuh dengan betul.", "kriteriaKejayaan": "(1) Murid boleh mendefinisikan sendi sebagai tempat pertemuan dua atau lebih tulang. (2) Murid boleh melakonkan gerakan sendi tertentu (contoh: putaran sendi bahu).", "setInduksi": "Guru melilitkan pembaris panjang pada siku seorang murid menggunakan kain anduh. Murid diminta cuba membengkokkan tangannya untuk mengambil pensel. Sesi perbincangan tercetus (5 minit).", "penyampaian": ["Murid membaca kisah tangan Ravi yang dibalut kain anduh (Buku Teks m/s 22-23).", "Murid meneliti rajah Kedudukan Sendi Manusia (Buku Teks m/s 22) untuk mengesan sendi leher, bahu, siku, lutut, pinggul, pergelangan tangan, dan pergelangan kaki.", "Murid melaksanakan aktiviti fizikal ringkas meniru pergerakan atlet dan penari (Buku Teks m/s 23-24).", "Murid mengaitkan gerakan putaran leher dan putaran lengan dengan fungsi sendi bahu dan leher."], "penutup": "Murid membuat kesimpulan bahawa tanpa sendi, seluruh badan manusia akan menjadi kaku seperti patung kayu.", "pentaksiran": "Lembaran latihan membulatkan kedudukan sendi (Buku Teks m/s 46 - Asah Minda).", "bahanBantuBelajar": "Kain anduh, kad gambar aktiviti fizikal, gambar rajah rangka sendi.", "refleksi": ""}, {"id": 17, "title": "Unit 2: Manusia", "minggu": 9, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "Unit 2: Manusia", "standardKandungan": "2.1 Sistem Rangka Manusia", "standardPembelajaran": "2.1.4高度 Menaakul kepentingan sistem rangka kepada tubuh manusia.; 2.1.5 Menjelaskan pemerhatian tentang sistem rangka manusia melalui lakaran, TMK, penulisan atau lisan secara kreatif.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat membina satu model rangka manusia menggunakan plastisin dan melabelkan fungsi perlindungan organ dalaman secara berkumpulan dengan kreatif.", "kriteriaKejayaan": "(1) Murid boleh menaakul akibat sekiranya otak tidak dilindungi oleh tengkorak. (2) Kumpulan boleh membentangkan model rangka yang siap dibina menggunakan plastisin sebagai wakil sendi.", "setInduksi": "Guru menunjukkan sebiji telur mentah yang diletakkan di dalam bekas plastik keras dan digoncang. Bekas mewakili tengkorak melindungi telur (otak) (5 minit).", "penyampaian": ["Murid membincangkan senario 4 situasi kemalangan/kecederaan rangka (Buku Teks m/s 25-26) untuk menaakul kepentingan sistem rangka.", "Murid melaksanakan Aktiviti Ria: Model Rangka Manusia (Buku Teks m/s 27).", "Secara berkumpulan, murid memotong gambar rangka, menyambung bahagian tulang menggunakan plastisin (simulasi sendi), dan melabelkannya pada kad manila.", "Ketua kumpulan membentangkan hasil kerja menggunakan kaedah *Gallery Walk* (lisan secara kreatif)."], "penutup": "Murid melengkapkan lembaran kerja taakulan kepentingan rangka.", "pentaksiran": "Penilaian hasil model rangka dan pembentangan lisan murid (PBD).", "bahanBantuBelajar": "Kad manila, plastisin, gambar tulang sistem rangka, gunting, gam, nota berpelekat.", "refleksi": ""}, {"id": 18, "title": "Unit 2: Manusia", "minggu": 9, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "Unit 2: Manusia", "standardKandungan": "2.2 Sistem Peredaran Darah Manusia", "standardPembelajaran": "2.2.1 Memerihalkan fungsi bahagian utama yang terlibat dalam sistem peredaran darah manusia.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat menyenaraikan 4 bahagian utama sistem peredaran darah (jantung, salur darah, darah, peparu) beserta fungsi utamanya dengan tepat.", "kriteriaKejayaan": "(1) Murid boleh menjelaskan perbezaan fungsi bahagian kiri jantung (mengepam darah kaya oksigen) dengan bahagian kanan jantung (darah kaya karbon dioksida). (2) Murid boleh mengaitkan salur darah sebagai tiub laluan pengaliran darah.", "setInduksi": "Guru menunjukkan botol air mineral kosong dengan pam penyembur air untuk menunjukkan konsep bagaimana jantung mengepam cecair (5 minit).", "penyampaian": ["Murid membaca senario amalan menderma darah (Buku Teks m/s 28).", "Guru menerangkan 4 komponen utama sistem peredaran darah manusia (Buku Teks m/s 28-29):", "Murid meneliti rajah keratan rentas jantung dan membandingkan peranan bahagian kiri (merah) dan kanan (biru) (Buku Teks m/s 28).", "Murid melukis peta buih bagi setiap fungsi komponen utama."], "penutup": "Murid menyanyikan lagu pendek tentang \"Sistem Aliran Darah Kita\" untuk mengukuhkan ingatan.", "pentaksiran": "Tugasan bertulis pengurusan grafik peta buih fungsi peredaran darah.", "bahanBantuBelajar": "Rajah keratan rentas jantung, model organ peredaran darah, Buku Teks m/s 28-29.", "refleksi": ""}, {"id": 19, "title": "Unit 2: Manusia", "minggu": 10, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "Unit 2: Manusia", "standardKandungan": "2.2 Sistem Peredaran Darah Manusia", "standardPembelajaran": "2.2.2 Melakar laluan peredaran darah yang lebih oksigen dan laluan peredaran darah yang lebih karbon dioksida dalam tubuh manusia.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat melakar rajah skematik laluan peredaran darah lebih oksigen (merah) dan darah lebih karbon dioksida (biru) dengan tepat.", "kriteriaKejayaan": "(1) Murid boleh melakar anak panah aliran dari peparu -> jantung -> tubuh (darah kaya oksigen) dengan betul. (2) Murid boleh melakar aliran dari tubuh -> jantung -> peparu (darah kaya karbon dioksida) dengan betul.", "setInduksi": "Guru menyembur air berwarna merah ke dalam satu bekas dan air biru ke bekas lain untuk merangsang konsep warna darah kaya gas berbeza (5 minit).", "penyampaian": ["Murid meneliti lakaran rajah skematik Laluan Peredaran Darah Manusia (Buku Teks m/s 30-31).", "Guru menerangkan peredaran secara berperingkat dari fasa menarik nafas sehingga menghembus nafas.", "Murid melaksanakan Aktiviti Ria: Melakar Laluan Peredaran Darah (Buku Teks m/s 32) secara berkumpulan.", "Murid menampal gambar organ pada kad manila dan menggunakan penyedut minuman berwarna merah dan biru untuk membentuk model salur darah yang menghubungkan peparu, jantung, dan tubuh."], "penutup": "Murid melukis anak panah aliran pada kad mereka untuk menunjukkan arah aliran dengan betul.", "pentaksiran": "Penilaian hasil lakaran model laluan peredaran darah kumpulan.", "bahanBantuBelajar": "Penyedut minuman (merah & biru), gambar organ, kad manila, Buku Teks m/s 30-32.", "refleksi": ""}, {"id": 20, "title": "Unit 2: Manusia", "minggu": 10, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "Unit 2: Manusia", "standardKandungan": "2.2 Sistem Peredaran Darah Manusia", "standardPembelajaran": "2.2.3 Merumuskan kepentingan sistem peredaran darah kepada tubuh manusia.; 2.2.4 Menjelaskan pemerhatian tentang sistem peredaran darah manusia secara kreatif.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat menulis sekurang-kurangnya 2 kepentingan utama sistem peredaran darah dan membentangkan rumusan tersebut secara kreatif.", "kriteriaKejayaan": "(1) Murid boleh menyatakan kepentingan mengangkut oksigen/nutrien ke seluruh tubuh. (2) Murid boleh menerangkan peranan darah dalam menyingkirkan bahan kumuh ke organ perkumuhan seperti ginjal.", "setInduksi": "Guru membawa lori mainan kecil yang membawa bongkah kayu (nutrien) dan mengambil bongkah plastik hitam (bahan kumuh) untuk menunjukkan analogi pengangkutan darah (5 minit).", "penyampaian": ["Murid meneliti teks tentang kepentingan sistem peredaran darah kepada tubuh manusia (Buku Teks m/s 33).", "Sesi perbincangan interaktif: Apa yang akan terjadi jika darah tidak mengangkut oksigen ke otak?", "Murid membina risalah (leaflet) ringkas bertajuk \"Darahku, Hayatku\" yang menerangkan kepentingan pengangkutan oksigen, air, nutrien, serta penyingkiran karbon dioksida dan bahan kumuh.", "Beberapa orang murid membentangkan risalah mereka di hadapan kelas secara bersahaja."], "penutup": "Guru mengukuhkan rumusan bahawa kegagalan sistem peredaran darah akan menghentikan seluruh sistem hidup manusia.", "pentaksiran": "Risalah kreatif murid tentang kepentingan sistem peredaran darah.", "bahanBantuBelajar": "Kertas berwarna, pensel warna, contoh risalah kesihatan, Buku Teks m/s 33.", "refleksi": ""}, {"id": 21, "title": "Unit 2: Manusia", "minggu": 11, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "Unit 2: Manusia", "standardKandungan": "2.3 Perkaitan antara Sistem di dalam Tubuh Manusia", "standardPembelajaran": "2.3.1 Menjelaskan melalui contoh perkaitan antara sistem dalam tubuh manusia.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat menghuraikan sekurang-kurangnya 2 perkaitan aktif antara sistem pernafasan, sistem peredaran darah, sistem rangka, dan sistem pencernaan manusia dengan betul.", "kriteriaKejayaan": "(1) Murid boleh menerangkan bagaimana sistem pernafasan membekalkan gas oksigen yang dihantar oleh sistem peredaran darah. (2) Murid boleh menjelaskan peranan sistem rangka melindungi jantung dan peparu.", "setInduksi": "Guru meminta murid menarik nafas sedalam-dalamnya dan merasai bagaimana tulang rusuk mereka naik dan turun, mengaitkan sistem rangka dengan sistem pernafasan (5 minit).", "penyampaian": ["Murid membaca pengenalan subtopik perkaitan antara sistem tubuh (Buku Teks m/s 34).", "Guru menerangkan rajah perkaitan sistem (Buku Teks m/s 35):", "Murid bekerjasama dalam kumpulan untuk membina rangkaian rantaian perkaitan menggunakan kad berwarna.", "Sesi pembentangan berkumpulan: \"Bagaimanakah sistem pencernaan membantu jantung terus mengepam darah?\"."], "penutup": "Murid merumuskan bahawa sistem tubuh manusia adalah satu ekosistem harmoni yang bekerjasama rapat.", "pentaksiran": "Hasil kerja membina kad perkaitan interaksi sistem tubuh.", "bahanBantuBelajar": "Kad imbasan interaksi sistem, pen penanda, Buku Teks m/s 34-35.", "refleksi": ""}, {"id": 22, "title": "Unit 2: Manusia", "minggu": 11, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "Unit 2: Manusia", "standardKandungan": "2.3 Perkaitan antara Sistem di dalam Tubuh Manusia", "standardPembelajaran": "2.3.1 Menjelaskan melalui contoh perkaitan antara sistem dalam tubuh manusia.; 2.3.2高度 Menaakul kepentingan penjagaan semua sistem dalam tubuh manusia supaya berfungsi dengan sempurna.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat menerangkan kesan kegagalan satu sistem tubuh terhadap sistem lain berdasarkan simulasi kes tercekik makanan atau kes patah tulang dengan betul.", "kriteriaKejayaan": "(1) Murid boleh menjelaskan mengapa tercekik makanan di esofagus boleh menyekat sistem pernafasan di trakea. (2) Murid boleh mengaitkan kecederaan tulang tangan yang patah dengan pembengkakan salur darah.", "setInduksi": "Guru menunjukkan gambar seseorang yang sedang tercekik makanan dan bertanya apakah sistem tubuh yang terlibat secara langsung (5 minit).", "penyampaian": ["Murid meneliti Situasi 1: Ketika tercekik makanan (Buku Teks m/s 36) yang menerangkan gangguan sistem pencernaan di esofagus menghalang sistem pernafasan di trakea.", "Murid meneliti Situasi 2: Ketika tulang patah (Buku Teks m/s 37) yang menerangkan kesan patah tulang rangka menjejaskan pengaliran darah.", "Murid membincangkan dalam kumpulan: \"Menaakul kepentingan menjaga keselamatan diri semasa makan dan bersukan berdasarkan rajah esofagus dan trakea.\"", "Setiap kumpulan melakonkan sketsa pendek durasi 2 minit menunjukkan situasi keselamatan tersebut."], "penutup": "Guru membuat rumusan kepentingan menaakul hubungan sebab-akibat kecederaan fizikal terhadap sistem tubuh yang luas.", "pentaksiran": "Lakonan sketsa pendek situasi kecederaan sistem tubuh.", "bahanBantuBelajar": "Gambar rajah esofagus & trakea, Buku Teks m/s 36-37.", "refleksi": ""}, {"id": 23, "title": "Unit 2: Manusia", "minggu": 12, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "Unit 2: Manusia", "standardKandungan": "2.3 Perkaitan antara Sistem di dalam Tubuh Manusia", "standardPembelajaran": "2.3.3 Menjana idea cara memelihara sistem dalam tubuh manusia bagi menjamin kehidupan yang sihat.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat menyenaraikan sekurang-kurangnya 5 amalan harian yang sihat untuk memelihara sistem rangka, pernafasan, peredaran darah, dan pencernaan dengan tepat.", "kriteriaKejayaan": "(1) Murid boleh menyatakan kepentingan diet kaya kalsium (susu) untuk rangka. (2) Murid boleh menyatakan bahaya merokok terhadap sistem pernafasan (peparu).", "setInduksi": "Guru membawa kotak susu segar dan sekotak rokok mainan kosong. Murid membincangkan impak kedua-dua bahan ini kepada sistem tubuh (5 minit).", "penyampaian": ["Murid meneroka pelbagai cara memelihara sistem tubuh berdasarkan panduan Buku Teks m/s 40-41:", "Murid membina peta pemikiran \"Gaya Hidup Sihatku\" di dalam buku nota.", "Sesi perkongsian idea: \"Bagaimanakah menangani masalah obesiti mengikut amalan penjagaan jantung?\"."], "penutup": "Murid membuat ikrar kelas untuk mengurangkan pengambilan makanan ringan bergula tinggi mulai hari ini.", "pentaksiran": "Peta pemikiran \"Gaya Hidup Sihatku\".", "bahanBantuBelajar": "Kotak susu, kad menu sihat, Buku Teks m/s 40-41.", "refleksi": ""}, {"id": 24, "title": "Unit 2: Manusia", "minggu": 12, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "Unit 2: Manusia", "standardKandungan": "2.3 Perkaitan antara Sistem di dalam Tubuh Manusia", "standardPembelajaran": "2.3.4 Menjelaskan pemerhatian tentang perkaitan antara sistem dalam tubuh manusia secara kreatif.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat melengkapkan borang senarai semak kesan kegagalan fungsi organ utama dan membentangkannya secara berkumpulan.", "kriteriaKejayaan": "(1) Kumpulan murid boleh menandakan \"X\" dengan betul pada sistem tubuh yang terjejas dalam senarai semak yang disediakan. (2) Murid boleh bekerjasama membentangkan hasil kerja kumpulan secara aktif.", "setInduksi": "Guru menampal sekeping senarai semak kosong di papan putih dan bertanya: \"Apakah yang terjejas jika enjin kereta (jantung) rosak?\" (5 minit).", "penyampaian": ["Murid menjalankan Aktiviti Ria: Senarai Semak Perkaitan Sistem di dalam Tubuh Manusia (Buku Teks m/s 42).", "Setiap kumpulan dibekalkan borang senarai semak yang mengandungi situasi \"Kegagalan peparu berfungsi\" atau \"Kegagalan fungsi jantung\".", "Murid berbincang dan menandakan \"X\" pada ruangan sistem rangka, pencernaan, peredaran darah, dan pernafasan yang akan turut terjejas.", "Murid membina poster pembentangan ringkas menerangkan hasil tandaan senarai semak tersebut.", "Setiap kumpulan membentangkan hasil kerja menggunakan teknik pameran di dinding kelas."], "penutup": "Guru membuat ulasan kepatuhan murid terhadap konsep kebergantungan sistem organ tubuh.", "pentaksiran": "Penilaian borang senarai semak perkaitan sistem.", "bahanBantuBelajar": "Kad manila, pen penanda, borang senarai semak sistem, Buku Teks m/s 42.", "refleksi": ""}, {"id": 25, "title": "Unit 3: Haiwan", "minggu": 13, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "Unit 3: Haiwan", "standardKandungan": "3.1 Kemandirian Spesies Haiwan", "standardPembelajaran": "3.1.1 Menyatakan maksud kemandirian spesies.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat menyatakan maksud kemandirian spesies sebagai keupayaan haiwan mengekalkan spesies bagi mengelakkan kepupusan dengan tepat melalui lisan atau penulisan.", "kriteriaKejayaan": "(1) Murid boleh menulis definisi kemandirian spesies dengan ejaan yang betul tanpa merujuk buku. (2) Murid boleh menerangkan mengapa kepupusan spesies merbahaya kepada keseimbangan alam.", "setInduksi": "Guru menunjukkan gambar dinosaur dan bertanya mengapa hidupan ini tidak boleh ditemui di taman bunga hari ini (5 minit).", "penyampaian": ["Murid membaca situasi dialog ketam dan belangkas di tepi pantai (Buku Teks m/s 50).", "Guru menerangkan konsep Kemandirian Spesies Haiwan: keupayaan haiwan mengekalkan keturunan dan spesiesnya agar tidak pupus dari muka Bumi.", "Murid berbincang tentang kepentingan memelihara haiwan terancam seperti penyu dan orang utan.", "Murid melengkapkan lembaran peta minda bertajuk \"Maksud Kemandirian Spesies\"."], "penutup": "Murid menyanyikan lagu \"Kemandirian Hidupan\" secara harmoni.", "pentaksiran": "Ujian tulisan ringkas definisi kemandirian spesies.", "bahanBantuBelajar": "Gambar dinosaur, kad gambar haiwan terancam, Buku Teks m/s 50.", "refleksi": ""}, {"id": 26, "title": "Unit 3: Haiwan", "minggu": 13, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "Unit 3: Haiwan", "standardKandungan": "3.1 Kemandirian Spesies Haiwan", "standardPembelajaran": "3.1.2 Menjelas dengan contoh ciri dan tingkah laku khas haiwan untuk melindungi diri daripada musuh.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat menyenaraikan sekurang-kurangnya 5 contoh ciri khas fizikal anggota badan haiwan yang melindunginya daripada serangan musuh berserta contoh haiwan yang tepat.", "kriteriaKejayaan": "(1) Murid boleh mengaitkan cangkerang keras dengan kura-kura, sengat bisa dengan lebah/lipan, dan bau busuk dengan pepijat. (2) Murid boleh menjelaskan bagaimana otot kaki kuat membantu kuda dan arnab melarikan diri.", "setInduksi": "Guru memainkan bunyi dengungan lebah yang kuat di dalam kelas dan bertanya bagaimana lebah mempertahankan dirinya daripada dicederakan (5 minit).", "penyampaian": ["Murid meneliti kisah pengembaraan Ana, Melia, dan Chan di dalam hutan (Buku Teks m/s 51-53).", "Murid mengenal pasti ciri-ciri khas fizikal:", "Murid bermain kad suai padan \"Ciri Khas vs Nama Haiwan\" secara berpasangan."], "penutup": "Murid merumuskan bahawa tuhan menganugerahkan ciri khas fizikal kepada haiwan untuk mempertahankan nyawa mereka.", "pentaksiran": "Lembaran kuiz padanan ciri fizikal haiwan.", "bahanBantuBelajar": "Kad suai padan ciri haiwan, Buku Teks m/s 51-53.", "refleksi": ""}, {"id": 27, "title": "Unit 3: Haiwan", "minggu": 14, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "Unit 3: Haiwan", "standardKandungan": "3.1 Kemandirian Spesies Haiwan", "standardPembelajaran": "3.1.2 Menjelas dengan contoh ciri dan tingkah laku khas haiwan untuk melindungi diri daripada musuh.; 3.1.3 Menjelas dengan contoh ciri dan tingkah laku khas haiwan untuk melindungi diri daripada cuaca melampau.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat menyenaraikan sekurang-kurangnya 3 tingkah laku khas haiwan melindungi diri daripada musuh dan 3 ciri khas bagi cuaca sejuk atau panas melampau dengan tepat.", "kriteriaKejayaan": "(1) Murid boleh membezakan antara ciri fizikal dengan tingkah laku khas (seperti memutuskan ekor, menyembur dakwat hitam, menggulungkan diri). (2) Murid boleh menerangkan fungsi bonggol unta dan lapisan lemak singa laut.", "setInduksi": "Guru menunjukkan gambar padang pasir gurun dan kutub utara yang bersalji, bertanyakan bagaimana haiwan boleh hidup di sana (5 minit).", "penyampaian": ["Murid membaca tentang tingkah laku khas mengembungkan badan (ikan buntal), memutuskan anggota badan (cicak/kurita), menyembur dakwat (sotong), menggulung diri (tenggiling), dan hidup berkumpulan (Buku Teks m/s 54-56).", "Murid mengkaji ciri cuaca melampau (Buku Teks m/s 58-62): beruang kutub (bulu tebal/hibernasi), penguin (bulu padat), unta (bonggol), musang gurun (telinga besar).", "Murid menjalankan projek Aktiviti Ria: Buku Poket Haiwan (Buku Teks m/s 63). Murid melipat kertas berwarna, menampal gambar haiwan beserta label ciri/tingkah laku melampau."], "penutup": "Murid membentangkan buku poket buatan sendiri kepada rakan sebelah.", "pentaksiran": "Buku Poket Haiwan (PBD hasil kerja).", "bahanBantuBelajar": "Kertas A4 warna, stapler, gambar cetak haiwan kutub/gurun, Buku Teks m/s 54-63.", "refleksi": ""}, {"id": 28, "title": "Unit 3: Haiwan", "minggu": 14, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "Unit 3: Haiwan", "standardKandungan": "3.1 Kemandirian Spesies Haiwan", "standardPembelajaran": "3.1.4 Mengenal pasti cara haiwan melindungi telurnya.; 3.1.5 Mengenal pasti cara haiwan memastikan anaknya terus hidup.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat mengenal pasti sekurang-kurangnya 3 cara haiwan melindungi telur dan 3 cara memastikan anaknya terus hidup berdasarkan jenis hidupan yang betul.", "kriteriaKejayaan": "(1) Murid boleh menerangkan kaedah lendir katak, menyembunyikan telur burung belatuk, dan menimbus telur penyu/kura-kura. (2) Murid boleh menyatakan peranan buaya/tilapia yang membawa anak di dalam mulut.", "setInduksi": "Guru menunjukkan sarang burung tiruan yang mengandungi telur kecil, bertanyakan bagaimana burung menjaga telurnya daripada ular (5 minit).", "penyampaian": ["Murid membaca drama kisah \"Raja Rimba\" menitahkan haiwan melindungi telur (Buku Teks m/s 64-65).", "Murid mengelaskan haiwan berdasarkan cara menjaga telur: katak/kodok (lendir busuk), burung (mengeram), lipas (tersorok), belalang/penyu (menimbus dalam tanah/pasir).", "Murid meneliti peranan menyusukan anak (mamalia), menyimpan anak di kantung (kanggaru), membawa anak dalam mulut (ikan tilapia, buaya), dan menyerang musuh (ayam, monyet) (Buku Teks m/s 67-68).", "Murid menjalankan simulasi drama ringkas Aktiviti Ria: Main Peranan (Buku Teks m/s 66) secara berkumpulan di hadapan kelas."], "penutup": "Guru membuat penutupan kognitif tentang kelangsungan spesies demi kelangsungan rantai makanan sejagat.", "pentaksiran": "Pemerhatian amali Main Peranan murid.", "bahanBantuBelajar": "Sampul surat berisi kad gambar haiwan bertelur/beranak, Buku Teks m/s 64-68.", "refleksi": ""}, {"id": 29, "title": "Unit 3: Haiwan", "minggu": 15, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "Unit 3: Haiwan", "standardKandungan": "3.2 Model Haiwan", "standardPembelajaran": "3.2.1 Mencipta model haiwan imaginasi yang boleh melindungi diri daripada musuh dan cuaca melampau.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat melakar satu gambar rajah lengkap model haiwan imaginasi beserta label fungsi sekurang-kurangnya 4 ciri khas keselamatan pada sehelai kertas dengan kemas.", "kriteriaKejayaan": "(1) Murid boleh menggabungkan ciri fizikal perlindungan (seperti duri, sisik, bulu tebal) ke dalam rekaan haiwan tersendiri. (2) Murid boleh memberikan nama kreatif untuk model haiwan imaginasi tersebut.", "setInduksi": "Guru menunjukkan contoh model haiwan imaginasi \"Muri-muri\" yang dihasilkan oleh Ana (Buku Teks m/s 72) dan membincangkan ciri luar biasanya (5 minit).", "penyampaian": ["Murid membaca pengenalan kempen kitar semula Panitia Sains SK Zamrud (Buku Teks m/s 70-71).", "Murid mengkaji rajah model Muri-muri yang mempunyai sesungut peka, sayap terbang tinggi, kuku cakar, sisik pelindung, bulu tebal, duri tajam, dan lemak tebal (Buku Teks m/s 72).", "Murid melaksanakan Aktiviti Ria: Haiwan Imaginasi (Buku Teks m/s 73).", "Setiap murid merangka reka bentuk tersendiri, melakar model di atas kertas A4, mewarnakan lakaran, dan melabelkan peranan setiap anggota rekaan fizikal secara individu."], "penutup": "Murid mengumpulkan semua lakaran untuk semakan awal bagi persiapan membina model fizikal.", "pentaksiran": "Lakaran rajah bersimbol haiwan imaginasi bertulis.", "bahanBantuBelajar": "Kertas A4, pensel warna, contoh lakaran \"Muri-muri\", Buku Teks m/s 70-73.", "refleksi": ""}, {"id": 30, "title": "Unit 3: Haiwan", "minggu": 15, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "Unit 3: Haiwan", "standardKandungan": "3.2 Model Haiwan", "standardPembelajaran": "3.2.2高度 Menaakul ciri khas pada model haiwan imaginasi bagi melindungi diri daripada musuh dan cuaca melampau.; 3.2.3 Menjelaskan pemerhatian tentang model haiwan imaginasi secara kreatif.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat membentangkan model lakaran haiwan imaginasi yang dibina dan menaakul secara saintifik fungsi perlindungan setiap organ rekaannya di hadapan rakan dengan yakin.", "kriteriaKejayaan": "(1) Murid boleh menjawab soalan rakan tentang bagaimana haiwan imaginasinya bertahan dalam cuaca gurun/kutub. (2) Murid boleh mengaitkan rekaan haiwan dengan kestabilan rantaian ekosistem.", "setInduksi": "Guru meminta beberapa orang murid mempamerkan lakaran haiwan imaginasi mereka di papan hitam (5 minit).", "penyampaian": ["Murid bersedia dengan hasil lakaran yang telah dimurnikan pada kelas lepas (Buku Teks m/s 73).", "Setiap murid secara bergilir-gilir tampil di hadapan kelas untuk membentangkan rekaan mereka (Aktiviti Ria m/s 73 langkah 5).", "Sesi soal jawab dan taakulan: \"Apakah yang terjadi sekiranya bulu tebal pada haiwan kamu dibuang?\" (Menaakul m/s 73 soalan a-d).", "Murid mengaitkan penciptaan ciri oleh Tuhan pada haiwan sebenar bagi mengekalkan keseimbangan alam."], "penutup": "Guru memberikan pujian atas daya kreativiti murid dan menekankan aplikasi pembelajaran sains hayat secara meluas.", "pentaksiran": "Pembentangan lisan dan keupayaan menaakul reka bentuk haiwan.", "bahanBantuBelajar": "Hasil lakaran murid, Buku Teks m/s 73.", "refleksi": ""}, {"id": 31, "title": "Unit 3: Haiwan", "minggu": 16, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "Unit 3: Haiwan", "standardKandungan": "3.3 Hubungan Makanan antara Hidupan", "standardPembelajaran": "3.3.1 Menyatakan maksud rantai makanan.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat menerangkan definisi rantai makanan sebagai hubungan makanan antara hidupan dengan betul dan membina sekurang-kurangnya 2 contoh rantai makanan lengkap berdasarkan ekosistem paya bakau.", "kriteriaKejayaan": "(1) Murid boleh mentakrifkan rantai makanan dengan tepat. (2) Murid boleh menggunakan anak panah ($", "setInduksi": "Guru menceritakan situasi sekumpulan memerang menangkap ikan di muara sungai (Buku Teks m/s 74). Murid membincangkan interaksi tersebut (5 minit).", "penyampaian": ["Murid meneroka situasi hidupan paya bakau: ketam, ular, helang, bangau, monyet, udang galah, tupai, burung (Buku Teks m/s 74-75).", "Guru menerangkan konsep Rantai Makanan (Buku Teks m/s 75).", "Murid membina hubungan linear menggunakan gambar fizikal: buah-buahan $", "Murid membina satu lagi rantai makanan alternatif berdasarkan hidupan paya bakau di atas kertas latihan."], "penutup": "Murid menyanyi lagu pendek \"Siapa Makan Siapa\" untuk melancarkan pemahaman simbol anak panah.", "pentaksiran": "Lembaran kerja membina rantai makanan.", "bahanBantuBelajar": "Gambar hidupan paya bakau, tali penyambung, kad simbol anak panah.", "refleksi": ""}, {"id": 32, "title": "Unit 3: Haiwan", "minggu": 16, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "Unit 3: Haiwan", "standardKandungan": "3.3 Hubungan Makanan antara Hidupan", "standardPembelajaran": "3.3.2 Mengenal pasti pengeluar dan pengguna dalam rantai makanan.; 3.3.3 Merumus tentang hubungan makanan antara hidupan dengan proses fotosintesis dari aspek perpindahan tenaga berdasarkan rantai makanan.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat membezakan peranan pengeluar (tumbuhan hijau) dan pengguna (haiwan) serta menerangkan bagaimana tenaga cahaya matahari dipindahkan melalui rantai makanan dengan tepat.", "kriteriaKejayaan": "(1) Murid boleh melabelkan tumbuhan sebagai pengeluar kerana menjalankan fotosintesis. (2) Murid boleh melakar rajah pengaliran tenaga dari matahari -> pengeluar -> pengguna.", "setInduksi": "Guru menyalakan lampu suluh ke arah daun pokok hiasan di makmal, bertanya dari mana pokok mendapat makanan (5 minit).", "penyampaian": ["Murid membaca perbincangan tentang pengeluar dan pengguna (Buku Teks m/s 77-78).", "Guru menjelaskan mengapa haiwan tidak boleh menjadi pengeluar (tiada fotosintesis).", "Murid mengkaji rajah Hubungan Makanan dengan Proses Fotosintesis (Buku Teks m/s 79-81).", "Murid melakar aliran tenaga yang bermula dari Matahari sebagai sumber tenaga utama ekosistem (Buku Teks m/s 80).", "Murid membincangkan aliran perpindahan tenaga: setiap kali hidupan memakan hidupan lain, sebahagian tenaga dipindahkan kepada pengguna seterusnya (Buku Teks m/s 78)."], "penutup": "Murid melengkapkan latihan ringkas mengelaskan tumbuhan dan haiwan mengikut peranan tenaga.", "pentaksiran": "Tugasan membina rajah aliran perpindahan tenaga bermula dari Matahari.", "bahanBantuBelajar": "Lampu suluh, tumbuhan makmal, rajah ekosistem sawah padi, Buku Teks m/s 77-81.", "refleksi": ""}, {"id": 33, "title": "Unit 3: Haiwan", "minggu": 17, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "Unit 3: Haiwan", "standardKandungan": "3.3 Hubungan Makanan antara Hidupan", "standardPembelajaran": "3.3.4 Menyatakan maksud siratan makanan.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat mentakrifkan siratan makanan sebagai gabungan beberapa rantai makanan dalam suatu habitat dengan betul dan mengasingkan sekurang-kurangnya 3 rantai makanan daripada satu siratan makanan yang diberikan.", "kriteriaKejayaan": "(1) Murid boleh menulis definisi siratan makanan secara bebas. (2) Murid boleh mengesan rantaian makanan individu di dalam rajah siratan makanan kebun sayur.", "setInduksi": "Guru melukis rangkaian benang bersilang-selang di papan hitam dan bertanya: \"Apakah yang menyerupai sarang labah-labah ini dalam hubungan makanan?\" (5 minit).", "penyampaian": ["Murid membaca penerangan siratan makanan kebun sayur (Buku Teks m/s 82).", "Guru membimbing murid menganalisis bagaimana 5 rantai makanan individu (a hingga e) digabungkan untuk membentuk satu Siratan Makanan (Buku Teks m/s 82).", "Murid bekerja berpasangan mengenal pasti bilangan pengguna yang memakan sayur (itik, kambing, ayam, beluncas).", "Murid menyalin rajah siratan makanan kebun sayur ke dalam buku latihan dan mewarnakan laluan rantai yang berbeza."], "penutup": "Murid mengulang sebut maksud siratan makanan secara kelas.", "pentaksiran": "Tugasan mengasingkan rantai makanan daripada siratan makanan.", "bahanBantuBelajar": "Benang, rajah siratan kebun sayur, Buku Teks m/s 82.", "refleksi": ""}, {"id": 34, "title": "Unit 3: Haiwan", "minggu": 17, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "Unit 3: Haiwan", "standardKandungan": "3.3 Hubungan Makanan antara Hidupan", "standardPembelajaran": "3.3.5 Membina siratan makanan di pelbagai habitat.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat membina satu siratan makanan yang lengkap berdasarkan hidupan di habitat kolam secara berkumpulan menggunakan kad gambar dengan betul.", "kriteriaKejayaan": "(1) Kumpulan boleh menyusun rumpai air sebagai pengeluar di pusat permulaan siratan. (2) Murid boleh menyambung laluan anak panah dengan arah aliran tenaga yang tepat ke arah pemangsa teratas (bangau).", "setInduksi": "Guru menunjukkan gambar kolam ikan dan bertanya apa yang akan berlaku kepada katak jika semua belalang ditangkap (5 minit).", "penyampaian": ["Murid mengkaji hidupan kolam: rumpai air, ikan kecil, ikan besar, berudu, katak, bangau, belalang, siput (Buku Teks m/s 83-84).", "Murid melaksanakan Aktiviti Ria: Siratan Makanan (Buku Teks m/s 85) secara berkumpulan.", "Setiap kumpulan menerima gambar habitat yang berbeza (sawah padi, kolam, hutan).", "Murid mengelompokkan pengeluar dan pengguna, membina rantaian, dan menggabungkannya di atas kad manila menjadi siratan makanan yang lengkap.", "Setiap kumpulan membentangkan hasil siratan makanan mereka di hadapan kelas."], "penutup": "Murid membincangkan kepelbagaian pilihan makanan haiwan dalam siratan makanan meningkatkan peluang kelangsungan spesies mereka.", "pentaksiran": "Penilaian projek poster siratan makanan (PBD).", "bahanBantuBelajar": "Gambar hidupan kolam, kad manila, gam, pen penanda, Buku Teks m/s 83-85.", "refleksi": ""}, {"id": 35, "title": "Unit 3: Haiwan", "minggu": 18, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "Unit 3: Haiwan", "standardKandungan": "3.3 Hubungan Makanan antara Hidupan", "standardPembelajaran": "3.3.6 Meramalkan kesan terhadap hidupan lain jika berlaku perubahan populasi dalam siratan makanan suatu habitat.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat meramalkan sekurang-kurangnya 2 kesan ekologi yang terjadi apabila satu populasi hidupan berkurang atau bertambah dalam siratan makanan dengan betul.", "kriteriaKejayaan": "(1) Murid boleh menyatakan sebab gangguan populasi seperti pemburuan haram, kebakaran hutan, atau pencemaran air. (2) Murid boleh merangka rantaian impak kemusnahan sayur akibat banjir terhadap kambing dan ular.", "setInduksi": "Guru menunjukkan keratan akhbar bertajuk \"Kebakaran Hutan Australia Mengorbankan Jutaan Koala\" (Buku Teks m/s 88) untuk merangsang kesedaran ekologi (5 minit).", "penyampaian": ["Murid meneliti situasi gangguan populasi (Buku Teks m/s 86-87):", "Guru menerangkan faktor pencetus perubahan populasi: penerokaan hutan tidak terancang, kebakaran hutan, dan pemburuan haram (Buku Teks m/s 87).", "Murid bekerja dalam kumpulan mensimulasikan kesan penurunan populasi tikus sawah padi terhadap helang dan ular.", "Setiap kumpulan merumuskan bagaimana ketidakseimbangan populasi boleh meruntuhkan seluruh siratan makanan."], "penutup": "Murid membuat catatan refleksi bertulis tentang tanggungjawab manusia menjaga kelestarian alam.", "pentaksiran": "Pembentangan kertas idea ramalan perubahan populasi.", "bahanBantuBelajar": "Keratan akhbar, gambar rajah siratan sawah padi, Buku Teks m/s 86-88.", "refleksi": ""}, {"id": 36, "title": "Unit 3: Haiwan", "minggu": 18, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "Unit 3: Haiwan", "standardKandungan": "3.3 Hubungan Makanan antara Hidupan", "standardPembelajaran": "3.3.7 Menjelaskan pemerhatian tentang hubungan makanan antara hidupan secara kreatif.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat membina satu rekaan terarium mini atau lakaran ekosistem lengkap yang mempamerkan interaksi pengeluar-pengguna dengan betul.", "kriteriaKejayaan": "(1) Murid boleh mengaplikasikan pengetahuan rantai makanan ke dalam reka bentuk ekosistem buatan. (2) Murid boleh menjelaskan peranan cahaya matahari dalam terarium tersebut.", "setInduksi": "Guru menunjukkan contoh bekas lutsinar kecil yang mengandungi tanah, rumput, dan ulat gonggok, menjelaskan istilah Terarium (5 minit).", "penyampaian": ["Murid membaca panduan projek pengayaan Santai Sains: Terarium Mini (Buku Teks m/s 89).", "Murid merancang komponen terarium: batu-batu kecil, tanah, tumbuh-tumbuhan kecil, dan organisma kecil (seperti semut atau ulat).", "Murid melakarkan pelan terarium mereka dan membina rajah siratan makanan mikro yang wujud di dalam terarium tersebut.", "Sesi pembentangan reka bentuk terarium: Bagaimana tumbuhan membekalkan oksigen kepada hidupan mikro di dalamnya melalui fotosintesis.", "Murid menjawab soalan-soalan penilaian \"Asah Minda\" Buku Teks m/s 91-92 secara bertulis."], "penutup": "Guru merumuskan semua topik Unit 3: Haiwan dan mengucapkan tahniah kepada murid sebelum cuti penggal bermula.", "pentaksiran": "Penilaian buku latihan (Asah Minda Unit 3) dan draf projek Terarium.", "bahanBantuBelajar": "Contoh terarium mini, lakaran ekosistem, Buku Teks m/s 89-92.", "refleksi": ""}, {"id": 37, "title": "Unit 4: Tumbuh-tumbuhan", "minggu": 19, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "Unit 4: Tumbuh-tumbuhan", "standardKandungan": "4.1 Kemandirian Spesies Tumbuhan", "standardPembelajaran": "4.1.1 Menjelas dengan contoh ciri khas tumbuhan untuk melindungi diri daripada musuh.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat menamakan sekurang-kurangnya 5 jenis ciri khas tumbuhan beserta contoh tumbuhan untuk melindungi diri daripada gangguan musuh dengan tepat.", "kriteriaKejayaan": "(1) Murid boleh memadankan ciri berduri tajam (durian), getah melekit (nangka), bulu halus (buluh), beracun (alamanda), dan berbau busuk (bunga tahi ayam) dengan betul. (2) Murid boleh menjelaskan bagaimana ciri gatal daun buluh melindungi tumbuhan tersebut.", "setInduksi": "Guru meletakkan sebiji buah durian di atas meja guru, meminta seorang murid cuba memegangnya dan bertanya bagaimana duri durian membantu pokok durian bermandiri (5 minit).", "penyampaian": ["Murid meneliti kisah pengembaraan Melia di kebun datuknya (Buku Teks m/s 94-96).", "Murid diterangkan 5 ciri khas perlindungan diri tumbuhan:", "Murid melaksanakan Aktiviti Ria: Perisai Tumbuh-tumbuhan (Buku Teks m/s 97). Murid bergerak mengikut stesen untuk mengenal pasti ciri khas 25 keping kad gambar tumbuhan yang diletakkan secara rawak.", "Murid menulis jawapan pada nota berpelekat dan memasukkannya ke dalam bekas stesen."], "penutup": "Murid membina peta minda di atas kertas graf dari hasil perbincangan stesen.", "pentaksiran": "Peta minda grafik ciri perlindungan diri tumbuhan.", "bahanBantuBelajar": "Buah durian/nanas sebenar, kad gambar tumbuhan stesen, Buku Teks m/s 94-97.", "refleksi": ""}, {"id": 38, "title": "Unit 4: Tumbuh-tumbuhan", "minggu": 19, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "Unit 4: Tumbuh-tumbuhan", "standardKandungan": "4.1 Kemandirian Spesies Tumbuhan", "standardPembelajaran": "4.1.2 Menjelas dengan contoh ciri khas tumbuhan untuk menyesuaikan diri dengan iklim dan perubahan musim.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat menyenaraikan adaptasi tumbuhan terhadap musim angin kencang, iklim panas, dan iklim sejuk dengan tepat melalui pembinaan poskad digital.", "kriteriaKejayaan": "(1) Murid boleh menerangkan mengapa pokok kelapa mempunyai batang mudah lentur dan daun berpecah-pecah. (2) Murid boleh menerangkan fungsi daun berlilin pokok keladi dan penggantungan daun pokok getah semasa musim kering.", "setInduksi": "Guru memainkan video pokok kelapa ditiup angin ribut pantai tetapi tidak tumbang, merangsang perbincangan penyesuaian fizikal (5 minit).", "penyampaian": ["Murid mengkaji ciri adaptasi iklim (Buku Teks m/s 98-102):", "Murid melaksanakan Aktiviti Ria: Poskad Digital (Buku Teks m/s 103) secara individu menggunakan komputer/tablet makmal komputer.", "Murid merangka teks poskad membincangkan keunikan pokok pinang menyesuaikan diri dengan iklim kencang (Buku Teks m/s 103).", "Murid memuat naik poskad digital ke dalam platform Google Classroom kelas."], "penutup": "Guru menunjukkan ulasan poskad terbaik di hadapan kelas.", "pentaksiran": "Poskad digital murid di Google Classroom (PBD TMK).", "bahanBantuBelajar": "Komputer/tablet makmal, video angin kencang, Buku Teks m/s 98-103.", "refleksi": ""}, {"id": 39, "title": "Unit 4: Tumbuh-tumbuhan", "minggu": 20, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "Unit 4: Tumbuh-tumbuhan", "standardKandungan": "4.2 Pencaran Biji Benih", "standardPembelajaran": "4.2.1 Menyatakan cara tumbuhan memencarkan biji benih atau buah.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat menyenaraikan 4 agen pencaran biji benih (angin, air, haiwan & manusia, mekanisme letupan) beserta satu contoh buah yang betul.", "kriteriaKejayaan": "(1) Murid boleh menjelaskan kepentingan biji benih dipencarkan jauh dari pokok induk. (2) Murid boleh mengenal pasti ejen pencaran bagi buah keembung dan angsana.", "setInduksi": "Guru memicit buah keembung yang matang sehingga ia merekah dan memencarkan biji benihnya secara tiba-tiba di depan kelas (5 minit).", "penyampaian": ["Murid meneliti kisah bergambar biji benih pokok keembung dan induknya (Buku Teks m/s 104-107).", "Guru menerangkan maksud Pencaran Biji Benih: proses penyebaran biji benih jauh daripada pokok induk bagi mengelakkan persaingan mendapatkan air, cahaya, ruang, dan nutrien.", "Murid membincangkan 4 cara pencaran:", "Murid menyalin peta minda ringkas tentang ejen-ejen pencaran tersebut."], "penutup": "Murid membuat kesimpulan tentang peri pentingnya pencaran bagi memastikan tumbesaran sihat anak pokok.", "pentaksiran": "Lembaran kerja mencatatkan ejen pencaran tumbuhan.", "bahanBantuBelajar": "Buah keembung matang, Buku Teks m/s 104-107.", "refleksi": ""}, {"id": 40, "title": "Unit 4: Tumbuh-tumbuhan", "minggu": 20, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "Unit 4: Tumbuh-tumbuhan", "standardKandungan": "4.2 Pencaran Biji Benih", "standardPembelajaran": "4.2.2 Menghubungkait cara pencaran dengan ciri biji benih atau buah.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat menghubungkaitkan sekurang-kurangnya 3 ciri fizikal biji benih dengan cara pencaran yang sepadan dengan tepat.", "kriteriaKejayaan": "(1) Murid boleh menerangkan mengapa biji benih pencaran angin (dandelion) mesti kecil, ringan, dan bersayap. (2) Murid boleh mengaitkan sabut berongga dan kulit berlilin (kelapa) dengan pencaran air.", "setInduksi": "Guru meniup biji benih dandelion atau kapas di udara makmal, meminta murid menerangkan mengapa ia boleh melayang lama di udara (5 minit).", "penyampaian": ["Murid meneliti ciri-ciri fizikal biji benih mengikut agen pencaran (Buku Teks m/s 105-107):", "Murid bermain permainan suai padan: \"Ciri Fizikal vs Ejen Pencaran\" secara berkumpulan.", "Murid melengkapkan lembaran kerja pengelasan ciri fizikal."], "penutup": "Murid merumuskan bahawa reka bentuk semulajadi biji benih dipadankan secara sempurna dengan ejen pencarannya.", "pentaksiran": "Tugasan bertulis padanan ciri fizikal biji benih dengan agen pencaran.", "bahanBantuBelajar": "Biji kapas/kapuk, gambar rajah struktur kelapa, Buku Teks m/s 105-107.", "refleksi": ""}, {"id": 41, "title": "Unit 4: Tumbuh-tumbuhan", "minggu": 21, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "Unit 4: Tumbuh-tumbuhan", "standardKandungan": "4.2 Pencaran Biji Benih", "standardPembelajaran": "4.2.3 Meramal cara pencaran bagi suatu biji benih berdasarkan ciri biji benih tersebut.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat meramal cara pencaran bagi sekurang-kurangnya 3 jenis biji benih berdasarkan ciri-ciri fizikal yang diperhatikan dengan betul.", "kriteriaKejayaan": "(1) Murid boleh mengenal pasti ciri fizikal biji benih (seperti bersayap, sabut berongga, atau bercangkuk). (2) Murid boleh menghubungkaitkan ciri fizikal dengan agen pencaran (angin, air, haiwan, atau mekanisme letupan).", "setInduksi": "Murid mengimbas kembali empat cara pencaran biji benih yang telah dipelajari (angin, air, haiwan/manusia, dan mekanisme letupan).", "penyampaian": ["Murid meneliti gambar dandelion, buah nipah, buah manggis, dan buah getah dalam buku teks halaman 108.", "Perbincangan Kumpulan: Murid berbincang dan meramal cara pencaran bagi setiap buah tersebut berdasarkan ciri-cirinya.", "Murid menjawab soalan ramalan: \"Antara cara pencaran tersebut, yang manakah memencarkan biji benih paling jauh daripada pokok induk? Mengapa?\"."], "penutup": "Murid merumuskan bahawa ciri khas biji benih membantu menentukan cara ia dipencarkan untuk menjamin kelangsungan spesies.", "pentaksiran": "Lisan dan latihan meramal cara pencaran.", "bahanBantuBelajar": "Buku teks m/s 108, kad gambar biji benih.", "refleksi": ""}, {"id": 42, "title": "Unit 4: Tumbuh-tumbuhan", "minggu": 21, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Hayat", "topik": "Unit 4: Tumbuh-tumbuhan", "standardKandungan": "4.2 Pencaran Biji Benih", "standardPembelajaran": "4.2.4 Menjelaskan pemerhatian tentang pencaran biji benih melalui lakaran, TMK, penulisan atau lisan secara kreatif.", "objektifPembelajaran": "Murid dapat menjelaskan hubungan antara ciri biji benih dengan cara pencarannya melalui pembinaan peta pemikiran dan menyatakan kepentingan kemandirian spesies kepada alam sekitar dengan betul.", "kriteriaKejayaan": "(1) Murid boleh membina peta pemikiran yang menghubungkaitkan ciri biji benih dengan agen pencaran secara sistematik. (2) Murid boleh menerangkan sekurang-kurangnya dua kepentingan kemandirian spesies (contoh: sumber makanan atau oksigen).", "setInduksi": "Guru menunjukkan gambar hutan yang luas dan bertanya bagaimana pokok-pokok tersebut tersebar tanpa ditanam oleh manusia.", "penyampaian": ["Aktiviti Ria (Kumpulan): Murid menjalankan aktiviti \"Biji Benih dan Cara Pencaran\" di halaman 110.", "Murid membina peta pemikiran pada kertas mahjung untuk menunjukkan hubung kait ciri biji benih dengan cara pencarannya.", "Sesi Menanaku: Murid berbincang tentang kepentingan kemandirian spesies:", "Setiap kumpulan membentangkan hasil kerja mereka secara kreatif (Gallery Walk)."], "penutup": "Murid membuat kesimpulan bahawa interaksi antara hidupan (pencaran oleh haiwan) membantu mengekalkan keseimbangan alam.", "pentaksiran": "Hasil kerja peta pemikiran dan pembentangan kreatif.", "bahanBantuBelajar": "Buku teks m/s 109-110, kertas mahjung, pen penanda.", "refleksi": ""}, {"id": 43, "title": "Unit 5: Elektrik", "minggu": 22, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Fizikal", "topik": "Unit 5: Elektrik", "standardKandungan": "5.1 Sumber Tenaga Elektrik", "standardPembelajaran": "5.1.1 Menjelas dengan contoh sumber yang menghasilkan tenaga elektrik.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat menamakan sekurang-kurangnya 5 sumber yang menghasilkan tenaga elektrik dalam kehidupan harian dengan tepat beserta fungsi ringkasnya.", "kriteriaKejayaan": "(1) Murid boleh menyatakan peranan sel suria yang menukarkan tenaga cahaya kepada elektrik. (2) Murid boleh memberikan contoh penggunaan dinamo pada basikal untuk menjana lampu.", "setInduksi": "Guru memutar roda basikal yang dilengkapi dinamo, murid memerhatikan lampu basikal menyala malap atau cerah mengikut kelajuan putaran roda (5 minit).", "penyampaian": ["Murid meneliti teks rangsangan sumber tenaga elektrik (Buku Teks m/s 116-117).", "Guru menerangkan peranan setiap sumber elektrik:", "Murid bekerja secara berkumpulan mengelaskan perkakas elektrik harian mengikut sumber elektrik yang sesuai."], "penutup": "Murid melengkapkan jadual pengelasan sumber tenaga elektrik di dalam buku latihan.", "pentaksiran": "Jadual latihan pengelasan sumber tenaga elektrik.", "bahanBantuBelajar": "Dinamo basikal, sel kering, akumulator, Buku Teks m/s 116-117.", "refleksi": ""}, {"id": 44, "title": "Unit 5: Elektrik", "minggu": 22, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Fizikal", "topik": "Unit 5: Elektrik", "standardKandungan": "5.2 Litar Bersiri dan Litar Selari", "standardPembelajaran": "5.2.1 Mengenal pasti susunan mentol secara bersiri dan selari dalam litar elektrik lengkap.; 5.2.2 Melakar rajah litar bersiri dan litar selari menggunakan simbol.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat mengenal pasti perbezaan susunan litar bersiri dan selari serta melakar kedua-dua rajah litar tersebut menggunakan simbol elektrik dengan betul.", "kriteriaKejayaan": "(1) Murid boleh menyatakan litar bersiri mempunyai 1 laluan manakala litar selari mempunyai lebih dari 1 laluan pengaliran arus. (2) Murid boleh melukis simbol sel kering, mentol, dan suis (terbuka/tertutup) mengikut standard DSKP.", "setInduksi": "Guru melukis gambar mentol dan bateri di papan hitam, bertanyakan murid cara menyambungkannya secara sistematik tanpa melukis bentuk fizikal objek (5 minit).", "penyampaian": ["Murid meneliti perbezaan susunan mentol litar bersiri (satu rantai) dan litar selari (cabang selari) (Buku Teks m/s 118-119).", "Guru memperkenalkan jadual komponen dan simbol standard (Buku Teks m/s 120).", "Murid melatih melakar litar bersiri dan selari mengikut langkah 1 hingga 3 (Buku Teks m/s 121).", "Murid menjalankan Aktiviti Ria: Melakar Rajah Litar Elektrik Menggunakan Simbol (Buku Teks m/s 122). Murid merujuk litar fizikal sebenar di atas meja lalu menterjemahkannya ke bentuk lakaran simbol pada kertas A4 menggunakan pembaris."], "penutup": "Murid membentangkan dan membandingkan hasil lakaran mereka untuk memastikan sambungan garis adalah lurus dan kemas.", "pentaksiran": "Amali melakar simbol litar elektrik (PBD).", "bahanBantuBelajar": "Komponen elektrik litar bersiri/selari, pembaris, kertas A4, Buku Teks m/s 118-122.", "refleksi": ""}, {"id": 45, "title": "Unit 5: Elektrik", "minggu": 23, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Fizikal", "topik": "Unit 5: Elektrik", "standardKandungan": "5.2 Litar Bersiri dan Litar Selari", "standardPembelajaran": "5.2.3 Membanding dan membezakan kecerahan mentol dalam litar bersiri dan litar selari.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat menerangkan perbezaan kecerahan mentol litar bersiri dan selari dan memberikan inferens saintifik yang tepat melalui aktiviti penyiasatan.", "kriteriaKejayaan": "(1) Murid boleh menyatakan mentol litar selari menyala lebih cerah berbanding litar bersiri. (2) Murid boleh membina inferens: mentol litar bersiri berkongsi arus elektrik pada laluan yang sama menyebabkan malap.", "setInduksi": "Guru menutup suis lampu dewan dan menyalakan litar bersiri & selari serentak. Murid membandingkan kecerahan nyalaan mentol (5 minit).", "penyampaian": ["Murid mengkaji penjelasan teoritis tentang pembahagian tenaga elektrik dalam litar bersiri dan selari (Buku Teks m/s 123).", "Murid menjalankan penyiasatan Mari Uji: Kecerahan Mentol (Buku Teks m/s 124).", "Murid membina satu litar bersiri dengan 2 mentol dan satu litar selari dengan 2 mentol menggunakan radas yang disediakan.", "Murid menutup suis secara serentak, memerhatikan perbezaan kecerahan, dan merekodkan hasil pemerhatian.", "Setiap kumpulan merumuskan kesimpulan hubungan jenis litar dengan kecerahan mentol."], "penutup": "Murid membincangkan aplikasi litar selari di rumah yang memberikan kecerahan lampu yang sekata.", "pentaksiran": "Pemerhatian amali dan lembaran jawapan \"Mari Uji\".", "bahanBantuBelajar": "Mentol, pemegang mentol, sel kering, pemegang sel kering, suis, wayar penyambung berklip buaya, Buku Teks m/s 123-124.", "refleksi": ""}, {"id": 46, "title": "Unit 5: Elektrik", "minggu": 23, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Fizikal", "topik": "Unit 5: Elektrik", "standardKandungan": "5.2 Litar Bersiri dan Litar Selari", "standardPembelajaran": "5.2.4 Mengeksperimen untuk membezakan kecerahan mentol dalam litar bersiri atau selari dengan mengubah bilangan mentol.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat membuktikan melalui eksperimen bahawa pertambahan bilangan mentol mengurangkan kecerahan litar bersiri tetapi tidak mengubah kecerahan litar selari.", "kriteriaKejayaan": "(1) Murid boleh menulis draf hipotesis tentang hubungan bilangan mentol dengan kecerahan dalam litar bersiri. (2) Murid boleh mengawal pemboleh ubah dimalarkan (jenis litar, bilangan sel kering) semasa eksperimen dijalankan.", "setInduksi": "Guru menambah bilangan mentol pada litar bersiri dari 1 kepada 3 mentol. Murid memerhatikan perubahan kecerahan mentol (5 minit).", "penyampaian": ["Murid merancang eksperimen berpandukan teori perbincangan bilangan mentol (Buku Teks m/s 127-128).", "Murid merumuskan hipotesis: \"Semakin bertambah bilangan mentol dalam litar bersiri, semakin berkurang kecerahan mentol\".", "Kumpulan 1 & 2 membina litar bersiri dengan 1, 2, dan 3 mentol (Litar A, B, C).", "Kumpulan 3 & 4 membina litar selari dengan 1, 2, dan 3 mentol.", "Murid mencatatkan pemerhatian kecerahan mentol ke dalam borang data yang disediakan.", "Murid mentafsir data: kecerahan mentol litar selari tidak berubah kerana setiap cabang mendapat bekalan tenaga bebas yang tersendiri."], "penutup": "Murid membentangkan kesimpulan eksperimen secara berkumpulan.", "pentaksiran": "Laporan bertulis eksperimen pengubahan bilangan mentol.", "bahanBantuBelajar": "Set lengkap komponen litar, pemegang mentol tambahan, Buku Teks m/s 127-128.", "refleksi": ""}, {"id": 47, "title": "Unit 5: Elektrik", "minggu": 24, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Fizikal", "topik": "Unit 5: Elektrik", "standardKandungan": "5.2 Litar Bersiri dan Litar Selari", "standardPembelajaran": "5.2.5 Mengeksperimen untuk membezakan kecerahan mentol dalam litar bersiri atau selari dengan mengubah bilangan sel kering.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat membuktikan melalui eksperimen bahawa pertambahan bilangan sel kering meningkatkan kecerahan mentol bagi litar bersiri dan litar selari dengan betul.", "kriteriaKejayaan": "(1) Murid boleh merumuskan hipotesis: \"Semakin bertambah bilangan sel kering, semakin bertambah kecerahan mentol\". (2) Murid boleh mencatatkan data pemerhatian kecerahan (paling cerah, cerah, malap) ke dalam jadual secara terperinci.", "setInduksi": "Guru menunjukkan dua lampu suluh: satu menggunakan 1 bateri (malap) dan satu menggunakan 3 bateri (sangat cerah), bertanya murid apa puncanya (5 minit).", "penyampaian": ["Murid merujuk panduan Eksperimen Kecerahan Mentol: Bilangan Sel Kering (Buku Teks m/s 125-126).", "Murid menetapkan pemboleh ubah: PM (bilangan sel kering), PB (kecerahan mentol), PD (bilangan mentol, jenis litar).", "Murid membina tiga litar bersiri (1 sel kering, 2 sel kering, 3 sel kering) mengikut langkah (a) hingga (c) (Buku Teks m/s 126).", "Murid mengulangi aktiviti bagi litar selari (Buku Teks m/s 127).", "Murid merekod data pemerhatian dalam jadual (Rujukan Buku Teks m/s 126)."], "penutup": "Murid menulis kesimpulan laporan eksperimen: Hipotesis Diterima.", "pentaksiran": "Penilaian laporan eksperimen \"Ubah Bilangan Sel Kering\" (PBD KPS).", "bahanBantuBelajar": "Enam sel kering, pemegang bateri, suis, mentol, Buku Teks m/s 125-127.", "refleksi": ""}, {"id": 48, "title": "Unit 5: Elektrik", "minggu": 24, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Fizikal", "topik": "Unit 5: Elektrik", "standardKandungan": "5.2 Litar Bersiri dan Litar Selari", "standardPembelajaran": "5.2.6 Menyatakan keadaan mentol apabila beberapa suis ditutup atau dibuka dalam litar bersiri dan litar selari dengan menjalankan aktiviti.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat meramal dan membuktikan keadaan mentol (menyala/tidak menyala) dalam litar bersiri dan selari apabila posisi beberapa suis diubah dengan betul.", "kriteriaKejayaan": "(1) Murid boleh menjelaskan mengapa litar bersiri padam sepenuhnya jika satu suis dibuka (litar tidak lengkap). (2) Murid boleh mengenal pasti laluan alternatif yang masih lengkap dalam litar selari apabila satu suis dibuka.", "setInduksi": "Guru menunjukkan pelan rumah ringkas dengan suis berasingan bagi bilik tidur dan bilik mandi, bertanya mengapa lampu tidur boleh menyala walaupun lampu mandi dipadamkan (5 minit).", "penyampaian": ["Murid meneliti simulasi posisi suis X dan Y pada litar bersiri dan litar selari (Buku Teks m/s 129-130).", "Murid menjalankan eksperimen Mari Uji: Tutup Suis, Buka Suis (Buku Teks m/s 131).", "Murid membina litar bersiri 3 mentol dengan 3 suis (S1, S2, S3) dan litar selari 3 mentol dengan 3 suis (S4, S5, S6) (Buku Teks m/s 131).", "Murid menukar kedudukan suis (ditutup/dibuka) secara berkumpulan mengikut arahan jadual kerja (Buku Teks m/s 131).", "Murid merekod pemerhatian keadaan mentol (menyala/tidak menyala) ke dalam jadual."], "penutup": "Murid membuat kesimpulan bertulis tentang kelonggaran kawalan arus yang ditawarkan oleh litar selari.", "pentaksiran": "Jadual laporan pemerhatian \"Tutup Suis, Buka Suis\".", "bahanBantuBelajar": "Enam suis, enam mentol, wayar penyambung, Buku Teks m/s 129-131.", "refleksi": ""}, {"id": 49, "title": "Unit 5: Elektrik", "minggu": 25, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Fizikal", "topik": "Unit 5: Elektrik", "standardKandungan": "5.3 Keselamatan dan Penjimatan Elektrik", "standardPembelajaran": "5.3.1 Menjana idea faktor yang mempengaruhi penggunaan tenaga elektrik.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat menyenaraikan sekurang-kurangnya 4 faktor dan 4 amalan bijak penjimatan elektrik di rumah berdasarkan analisis bil elektrik bulanan dengan betul.", "kriteriaKejayaan": "(1) Murid boleh membezakan kadar penggunaan kuasa lampu LED berbanding lampu filamen. (2) Murid boleh merangka peta pemikiran cara menjimatkan tenaga elektrik di rumah.", "setInduksi": "Guru mempamerkan sekeping bil elektrik bulanan rumah yang bernilai RM450 dan bertanya: \"Apakah amalan yang menyebabkan bil ini terlalu tinggi?\" (5 minit).", "penyampaian": ["Murid meneliti faktor yang mempengaruhi bil elektrik: jenis peralatan (lampu LED vs filamen) dan tempoh penggunaan (Buku Teks m/s 132-133).", "Murid melaksanakan Aktiviti Ria: Menganalisis Penggunaan Tenaga Elektrik di Rumah (Buku Teks m/s 134) secara berkumpulan.", "Murid menganalisis contoh bil elektrik beberapa bulan, membina carta palang perubahan kos bil, dan berbincang melalui temubual maya cara amalan keluarga rakan tersebut.", "Murid membina peta pemikiran mencadangkan cara penjimatan (padam lampu tidak diguna, tanggalkan plag, kurangkan pemanas air)."], "penutup": "Kumpulan membentangkan peta pemikiran \"Amalan Lestari Elektrik\" di papan putih.", "pentaksiran": "Analisis data bil elektrik dan pembentangan peta pemikiran.", "bahanBantuBelajar": "Salinan bil elektrik bulanan, kertas lukisan, Buku Teks m/s 132-134.", "refleksi": ""}, {"id": 50, "title": "Unit 5: Elektrik", "minggu": 25, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Fizikal", "topik": "Unit 5: Elektrik", "standardKandungan": "5.3 Keselamatan dan Penjimatan Elektrik", "standardPembelajaran": "5.3.2 Menjelas dengan contoh kesan kecuaian pengendalian peralatan elektrik.; 5.3.3 Memerihalkan langkah keselamatan ketika mengendalikan peralatan elektrik.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat menyatakan kesan kecuaian (renjatan, litar pintas, kebakaran) dan menghasilkan satu \"Kad Keselamatan Elektrik\" secara berkumpulan dengan betul.", "kriteriaKejayaan": "(1) Murid boleh menjelaskan bahaya membiarkan peranti dicas terlalu lama. (2) Murid boleh menyenaraikan 4 langkah keselamatan (contoh: keringkan tangan sebelum sentuh suis).", "setInduksi": "Guru menunjukkan gambar palam elektrik yang cair akibat beban lampau (multi-plug) untuk mencetuskan rasa gerun keselamatan (5 minit).", "penyampaian": ["Murid mengkaji bahaya elektrik (Buku Teks m/s 135-136): renjatan elektrik (memasukkan objek besi ke soket), litar pintas (wayar rosak), kebakaran (beban melampau).", "Murid mengkaji langkah keselamatan (Buku Teks m/s 137-138): baiki alat oleh bertauliah, pastikan tangan kering, ganti wayar rosak.", "Murid melaksanakan Aktiviti Ria: Kad Keselamatan dan Penjimatan Tenaga Elektrik (Buku Teks m/s 139) secara berkumpulan.", "Murid melawat kawasan sekolah (kantin, pusat sumber), menanda kawasan elektrik, membina kad panduan keselamatan dari kad manila, dan menampalkannya di tempat strategik."], "penutup": "Murid membentangkan rumusan kepentingan amalan keselamatan dalam mengendalikan elektrik seharian.", "pentaksiran": "Hasil ciptaan Kad Keselamatan Elektrik makmal/kantin.", "bahanBantuBelajar": "Kad manila, gunting, pen penanda, Buku Teks m/s 135-139.", "refleksi": ""}, {"id": 51, "title": "Unit 6: Haba", "minggu": 26, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Fizikal", "topik": "Unit 6: Haba", "standardKandungan": "6.1 Haba dan Suhu", "standardPembelajaran": "6.1.1 Menyatakan maksud haba dan suhu.; 6.1.2 Menyukat suhu dengan menggunakan alat dan unit piawai dengan teknik yang betul.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat membezakan maksud haba dan suhu serta menyukat suhu air paip, air sejuk, dan air panas menggunakan termometer dengan teknik pembacaan meniskus yang betul.", "kriteriaKejayaan": "(1) Murid boleh menyatakan suhu ialah darjah kepanasan/kesejukan objek dalam unit darjah Celsius (°C). (2) Murid boleh menyelaraskan mata setentang dengan aras meniskus termometer alkohol/merkuri dengan betul.", "setInduksi": "Guru meletakkan air batu dan air suam di depan murid. Murid mencelup jari dan membincangkan persepsi darjah kepanasan air (5 minit).", "penyampaian": ["Murid membaca pengenalan haba (tenaga yang dipindahkan) dan suhu (darjah kepanasan) (Buku Teks m/s 146).", "Guru menerangkan struktur termometer bilik dan termometer makmal (merkuri/alkohol) (Buku Teks m/s 147).", "Guru mendemonstrasikan langkah memegang termometer tegak, tidak menyentuh dasar bikar, dan membaca aras meniskus (Buku Teks m/s 147-148).", "Murid menjalankan eksperimen Mari Uji: Termometer (Buku Teks m/s 149).", "Murid menyukat suhu air paip, air panas, dan air sejuk, merekodkan ke dalam jadual, dan melukis carta palang data tersebut."], "penutup": "Murid membincangkan perbezaan antara termometer makmal alkohol (meniskus cekung) dan merkuri (meniskus cembung) (Buku Teks m/s 149).", "pentaksiran": "Amali penggunaan termometer (kemahiran manipulatif).", "bahanBantuBelajar": "Termometer makmal, bikar, air panas, ais, Buku Teks m/s 146-149.", "refleksi": ""}, {"id": 52, "title": "Unit 6: Haba", "minggu": 26, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Fizikal", "topik": "Unit 6: Haba", "standardKandungan": "6.1 Haba dan Suhu", "standardPembelajaran": "6.1.3 Menggunakan perhubungan ruang dan masa untuk melihat perubahan suhu apabila ais dipanaskan dan menentukan takat beku dan takat didih air.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat menentukan takat beku air (0°C) dan takat didih air (100°C) serta merekodkan perubahan suhu ais dipanaskan mengikut selang masa dengan tepat.", "kriteriaKejayaan": "(1) Murid boleh menyatakan takat beku air ialah 0°C dan takat didih air ialah 100°C. (2) Murid boleh memplotkan graf garis atau membina carta palang hubungan masa pemanasan dengan peningkatan suhu air.", "setInduksi": "Guru menyalakan penunu Bunsen di depan makmal, meletakkan bikar berisi ketulan ais di atasnya dan mencabar murid meneka bila suhu air akan berhenti meningkat (5 minit).", "penyampaian": ["Murid membaca kisah komik “Si Pengukur Suhu” (Buku Teks m/s 150).", "Murid menjalankan eksperimen Mari Uji: Takat Beku dan Takat Didih (Buku Teks m/s 151) secara berkumpulan.", "Murid menyediakan radas: kaki retort, tungku kaki tiga, kasa dawai, penunu Bunsen, bikar berisi ketulan ais, termometer, dan jam randik.", "Murid memanaskan ais, membaca suhu setiap 5 minit menggunakan jam randik sehingga air mendidih (Buku Teks m/s 151).", "Murid mencatatkan data ke dalam jadual dan membina carta palang pola peningkatan suhu."], "penutup": "Murid merumuskan pola perubahan suhu: \"Suhu meningkat semasa pemanasan sehingga takat didih 100°C dan kekal tetap\".", "pentaksiran": "Laporan eksperimen takat beku dan takat didih (PBD KPS).", "bahanBantuBelajar": "Penunu Bunsen, kaki retort, ketulan ais, bikar, termometer, jam randik, Buku Teks m/s 150-151.", "refleksi": ""}, {"id": 53, "title": "Unit 6: Haba", "minggu": 27, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Fizikal", "topik": "Unit 6: Haba", "standardKandungan": "6.1 Haba dan Suhu", "standardPembelajaran": "6.1.4 Memerihalkan perubahan suhu air apabila air panas disejukkan ke suhu bilik.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat menjelaskan konsep aliran haba dari kawasan panas ke sejuk dan merekodkan penurunan suhu air panas sehingga menyamai suhu bilik dengan betul.", "kriteriaKejayaan": "(1) Murid boleh menerangkan haba mengalir dari air panas ke persekitaran yang lebih sejuk. (2) Murid boleh menyatakan suhu air panas akan berhenti menurun apabila mencapai suhu bilik (suhu persekitaran).", "setInduksi": "Guru meletakkan secawan air mendidih di atas meja guru, murid meramalkan apa yang berlaku kepada suhu air tersebut selepas 1 jam dibiarkan (5 minit).", "penyampaian": ["Murid membaca penerangan pergerakan haba kopi panas ke persekitaran (Buku Teks m/s 152).", "Murid menjalankan eksperimen Mari Uji: Haba Mengalir (Buku Teks m/s 153).", "Murid menuangkan air panas ke dalam bikar, meletakkan termometer, dan mengambil bacaan suhu setiap 5 minit sehingga bacaan menjadi tetap (suhu bilik).", "Murid merekod data, membina carta palang, dan memuat naik tugasan tersebut ke platform Google Classroom.", "Perbincangan: \"Mengapa sudu besi menjadi panas apabila direndam dalam air panas?\" (Buku Teks m/s 152)."], "penutup": "Murid menyimpulkan bahawa haba mengalir dari objek bersuhu tinggi ke objek bersuhu rendah.", "pentaksiran": "Analisis carta palang dan jawapan Google Classroom.", "bahanBantuBelajar": "Air panas, bikar, termometer, jam randik, Google Classroom, Buku Teks m/s 152-153.", "refleksi": ""}, {"id": 54, "title": "Unit 6: Haba", "minggu": 27, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Fizikal", "topik": "Unit 6: Haba", "standardKandungan": "6.1 Haba dan Suhu", "standardPembelajaran": "6.1.5 Membuat kesimpulan tentang kesan ke atas bahan apabila menerima haba dan apabila kehilangan haba.; 6.1.6高度 Menaakul kepentingan aplikasi prinsip pengembangan dan pengecutan bahan dalam kehidupan harian.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat menyimpulkan kesan haba terhadap pengembangan/pengecutan pepejal, cecair, dan gas serta menaakul kepentingan aplikasinya (jambatan, landasan, kabel elektrik) dengan tepat.", "kriteriaKejayaan": "(1) Murid boleh membuktikan gas (belon) mengembang apabila menerima haba air panas. (2) Murid boleh menerangkan mengapa kabel elektrik dipasang kendur sedikit di antara tiang.", "setInduksi": "Guru memanaskan bebola besi di depan makmal, menunjukkan bebola besi mengembang dan tersangkut tidak lepas melalui gelung besi (5 minit).", "penyampaian": ["Murid mengkaji prinsip pengembangan dan pengecutan bahan (Buku Teks m/s 154).", "Murid menjalankan aktiviti penyiasatan dalam kumpulan (Buku Teks m/s 155-157):", "Murid menganalisis kepentingan aplikasi harian (Buku Teks m/s 158): ruang pada landasan kereta api, penyambung jambatan, kabel elektrik dipasang kendur."], "penutup": "Murid melengkapkan buku skrap digital mengenai prinsip pengembangan bahan dan memuat naik ke Google Classroom.", "pentaksiran": "Tugasan buku skrap digital dan laporan eksperimen.", "bahanBantuBelajar": "Set bebola & gelung besi, kelalang kon, belon, botol, Buku Teks m/s 154-159.", "refleksi": ""}, {"id": 55, "title": "Unit 7: Pengaratan", "minggu": 28, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Bahan", "topik": "Unit 7: Pengaratan", "standardKandungan": "7.1 Pengaratan Bahan", "standardPembelajaran": "7.1.1高度 Menyatakan ciri objek yang berkarat.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat menyatakan 3 ciri fizikal objek yang berkarat (warna perang kemerahan, permukaan kasar, rapuh) berdasarkan pemerhatian dengan tepat.", "kriteriaKejayaan": "(1) Murid boleh membezakan objek yang berkarat dengan objek yang tidak berkarat secara fizikal. (2) Murid boleh menulis jadual pemerhatian kerosakan engsel besi yang berkarat.", "setInduksi": "Guru membunyikan engsel pintu makmal yang sengaja tidak digris (\"kreeek!\") dan bertanya murid apakah punca bunyi bising tersebut (5 minit).", "penyampaian": ["Murid meneliti komik situasi pembuka tingkap dan engsel pintu yang berkarat (Buku Teks m/s 164).", "Murid diperkenalkan 3 ciri objek berkarat: berwarna perang kemerahan, permukaan kasar, dan bersifat rapuh (Buku Teks m/s 164).", "Murid melaksanakan Aktiviti Ria: Ciri-ciri Objek yang Berkarat (Buku Teks m/s 165) secara berkumpulan.", "Murid meninjau persekitaran sekolah mengesan objek besi yang berkarat, mencatat ciri kerosakan, dan mengumpul data dalam bentuk jadual di atas kertas berwarna."], "penutup": "Kumpulan membentangkan jadual penemuan objek berkarat di hadapan kelas.", "pentaksiran": "Jadual laporan ciri objek berkarat persekitaran sekolah.", "bahanBantuBelajar": "Kertas berwarna, kamera/telefon (pilihan), Buku Teks m/s 164-165.", "refleksi": ""}, {"id": 56, "title": "Unit 7: Pengaratan", "minggu": 28, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Bahan", "topik": "Unit 7: Pengaratan", "standardKandungan": "7.1 Pengaratan Bahan", "standardPembelajaran": "7.1.2 Mengitlak bahawa objek yang diperbuat daripada besi boleh berkarat.; 7.1.3 Mengeksperimen untuk menentukan faktor yang menyebabkan pengaratan.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat menyimpulkan objek diperbuat daripada besi sahaja yang boleh berkarat dan membuktikan faktor air & udara menyebabkan pengaratan melalui eksperimen jangka pendek dengan betul.", "kriteriaKejayaan": "(1) Murid boleh mengenal pasti jarum/paku besi boleh berkarat manakala rod kaca, lidi sate, penyedut minuman plastik tidak boleh berkarat. (2) Murid boleh mengawal kehadiran air dan udara menggunakan minyak dan kalsium klorida kontang.", "setInduksi": "Guru menunjukkan sebatang paku besi berkarat dan sebatang pembaris plastik bersih, bertanya mengapa pembaris plastik tidak berkarat (5 minit).", "penyampaian": ["Murid meneliti penyiasatan Mari Uji: Objek yang Berkarat (Buku Teks m/s 167) menggunakan cuka dan kapas basah selama 5 hari ke atas jarum, rod kaca, lidi sate, dan paku.", "Murid merancang eksperimen Menyiasat faktor-faktor pengaratan (Buku Teks m/s 168-169) secara berkumpulan.", "Murid melabelkan 4 tabung uji (A, B, C, D) dan memasukkan 20 g bulu besi (Buku Teks m/s 169):", "Murid membincangkan fungsi kalsium klorida kontang menyerap kelembapan dan minyak masak menghalang udara larut (Buku Teks m/s 169)."], "penutup": "Murid menyimpan tabung uji di rak makmal untuk diperhatikan pada minggu hadapan.", "pentaksiran": "Perancangan eksperimen dan kemahiran manipulatif penyediaan tabung uji.", "bahanBantuBelajar": "Tabung uji, bulu besi, kalsium klorida, minyak, air didih, Buku Teks m/s 167-169.", "refleksi": ""}, {"id": 57, "title": "Unit 7: Pengaratan", "minggu": 29, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Bahan", "topik": "Unit 7: Pengaratan", "standardKandungan": "7.1 Pengaratan Bahan", "standardPembelajaran": "7.1.3 Mengeksperimen untuk menentukan faktor yang menyebabkan pengaratan.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat mentafsir keputusan eksperimen bulu besi dan menyimpulkan bahawa kehadiran air dan udara adalah faktor wajib bagi proses pengaratan berlaku dengan betul.", "kriteriaKejayaan": "(1) Murid boleh menyatakan bulu besi dalam Tabung C berkarat manakala Tabung A & B kekal bersih. (2) Murid boleh membuat kesimpulan: \"Kehadiran air dan udara menyebabkan pengaratan besi\".", "setInduksi": "Murid mengambil semula rak tabung uji eksperimen bulu besi dari minggu lepas dan meletakkannya di atas meja untuk diperhatikan (5 minit).", "penyampaian": ["Murid memeriksa keadaan fizikal bulu besi di dalam Tabung Uji A, B, C, dan D (Rujukan Buku Teks m/s 169).", "Murid mencatatkan hasil pemerhatian ke dalam jadual (Data, Buku Teks m/s 169).", "Murid mentafsir data: Mengapa bulu besi dalam Tabung B (air didih + minyak) tidak berkarat (kerana tiada udara).", "Murid mengaitkan fungsi kalsium klorida kontang di Tabung A yang menyerap air (kelembapan).", "Setiap kumpulan membina kesimpulan bertulis membuktikan hipotesis diterima."], "penutup": "Murid mengemaskan radas, membasuh tabung uji, dan membersihkan meja makmal.", "pentaksiran": "Pentafsiran data laporan eksperimen pengaratan.", "bahanBantuBelajar": "Hasil eksperimen bulu besi minggu 28, Buku Teks m/s 169.", "refleksi": ""}, {"id": 58, "title": "Unit 7: Pengaratan", "minggu": 29, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Bahan", "topik": "Unit 7: Pengaratan", "standardKandungan": "7.1 Pengaratan Bahan", "standardPembelajaran": "7.1.4 Memerihalkan cara mencegah pengaratan.; 7.1.5 Menaakul kepentingan mencegah pengaratan.; 7.1.6 Menjelaskan pemerhatian tentang pengaratan bahan melalui lakaran, TMK, penulisan atau lisan secara kreatif.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat menyenaraikan 4 kaedah mencegah pengaratan dan menghasilkan satu poster \"Projek Pencegahan Pengaratan\" di kawasan sekolah secara berkumpulan dengan betul.", "kriteriaKejayaan": "(1) Murid boleh memadankan kaedah menyapu minyak/gris, mengecat, menyadur logam, dan menyalut plastik dengan betul. (2) Murid boleh menaakul kepentingan mencegah pengaratan bagi keselamatan pengguna.", "setInduksi": "Guru mempamerkan tin sardin yang kemik dan berkarat di bahagian bucu, bertanyakan murid adakah makanan di dalamnya selamat dimakan (5 minit).", "penyampaian": ["Murid meneliti teks kaedah mencegah pengaratan (Buku Teks m/s 170-171): mengecat (pagar), menyapu minyak/gris (rantai basikal), menyalut plastik (gantungan baju), menyadur logam (sudu keluli).", "Murid membincangkan 4 situasi kepentingan pencegahan (Buku Teks m/s 171-172): selamat digunakan, tahan lama, jimat kos, kelihatan cantik.", "Murid melaksanakan Aktiviti Ria: Projek Pencegahan Pengaratan (Buku Teks m/s 173).", "Setiap kumpulan merangka poster tindakan pencegahan karatan pagar atau peralatan sekolah, merakam foto keadaan sebelum-selepas, dan berkongsi di Google Classroom."], "penutup": "Guru membimbing murid merumuskan kepentingan penjagaan bahan besi.", "pentaksiran": "Poster projek pencegahan pengaratan.", "bahanBantuBelajar": "Cat, berus cat, gris, sarung tangan, Google Classroom, Buku Teks m/s 170-173.", "refleksi": ""}, {"id": 59, "title": "Unit 8: Jirim", "minggu": 30, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Bahan", "topik": "Unit 8: Jirim", "standardKandungan": "8.1 Keadaan Jirim", "standardPembelajaran": "8.1.1 Menyatakan jirim wujud dalam keadaan pepejal, cecair dan gas.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat mendefinisikan jirim sebagai bahan yang mempunyai jisim dan memenuhi ruang serta menyatakan 3 keadaan fizikal jirim dengan betul.", "kriteriaKejayaan": "(1) Murid boleh melafazkan definisi jirim secara bertulis. (2) Murid boleh menamakan 3 keadaan jirim (pepejal, cecair, gas).", "setInduksi": "Guru menuangkan air ke dalam gelas dan meniup belon, bertanyakan murid adakah air dan udara di dalam belon mempunyai persamaan sifat fizikal (5 minit).", "penyampaian": ["Murid menyanyikan pantun rangsangan Unit 8 Jirim (Buku Teks m/s 177).", "Guru menerangkan konsep Jirim: bahan yang mempunyai jisim dan memenuhi ruang (Buku Teks m/s 178).", "Murid mengkaji 3 keadaan jirim di kawasan pantai (Buku Teks m/s 178-179):", "Murid membina peta minda pengenalan jirim di buku latihan."], "penutup": "Murid memegang beberapa objek pepejal untuk merasai berat (jisim) dan isipadu ruang yang dipenuhi.", "pentaksiran": "Kuiz lisan definisi jirim.", "bahanBantuBelajar": "Bikar, air, belon, Buku Teks m/s 177-179.", "refleksi": ""}, {"id": 60, "title": "Unit 8: Jirim", "minggu": 30, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Bahan", "topik": "Unit 8: Jirim", "standardKandungan": "8.1 Keadaan Jirim", "standardPembelajaran": "8.1.2 Mengelas bahan atau objek berdasarkan keadaan jirim.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat mengelaskan sekurang-kurangnya 10 jenis bahan harian di sekolah ke dalam carta pengelasan pepejal, cecair, dan gas dengan betul secara berkumpulan.", "kriteriaKejayaan": "(1) Kumpulan boleh membezakan dadu, klip kertas, kicap, wap air, dan peluh mengikut keadaan jirim. (2) Murid boleh bekerjasama membina carta pengelasan grafik di atas kertas mahjung.", "setInduksi": "Guru meletakkan kotak pensel, botol kicap, dan penyembur minyak wangi di atas meja, meminta murid meneka keadaan jirim setiap objek tersebut (5 minit).", "penyampaian": ["Murid meninjau senarai bahan harian: dadu, klip kertas, peluh, kicap, wap air, sudu, minyak sawit, biskut (Rujukan Soalan Asah Minda m/s 197).", "Murid melaksanakan Aktiviti Ria: Mengelas Jirim (Buku Teks m/s 179) secara berkumpulan.", "Setiap kumpulan meneroka bilik darjah dan makmal, menyenaraikan bahan-bahan yang dijumpai, dan mengelaskannya ke dalam lajur Pepejal, Cecair, dan Gas pada kertas mahjung menggunakan pen penanda (Buku Teks m/s 179).", "Kumpulan membentangkan carta pengelasan di depan kelas melalui aktiviti pembentangan pendek."], "penutup": "Guru mengulas ketepatan pengelasan gas yang tidak kelihatan seperti oksigen dan karbon dioksida.", "pentaksiran": "Carta pengelasan jirim kertas mahjung (PBD).", "bahanBantuBelajar": "Kertas mahjung, pen penanda, Buku Teks m/s 179.", "refleksi": ""}, {"id": 61, "title": "Unit 8: Jirim", "minggu": 31, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Bahan", "topik": "Unit 8: Jirim", "standardKandungan": "8.1 Keadaan Jirim", "standardPembelajaran": "8.1.3 Mencirikan sifat pepejal, cecair dan gas dengan menjalankan aktiviti.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat mencirikan sifat pepejal, cecair, dan gas (bentuk, jisim, isipadu, memenuhi ruang) melalui siri eksperimen ringkas dengan tepat.", "kriteriaKejayaan": "(1) Murid boleh menyatakan pepejal mempunyai bentuk dan isipadu tetap. (2) Murid boleh menyatakan cecair mempunyai isipadu tetap tetapi bentuknya mengikut bentuk bekas.", "setInduksi": "Guru menuangkan air berwarna dari bikar ke dalam cawan berbentuk bintang. Murid memerhatikan perubahan bentuk air tersebut (5 minit).", "penyampaian": ["Murid mengkaji perbandingan sifat jirim (Buku Teks m/s 180-183).", "Murid menjalankan 3 eksperimen berkumpulan:", "Murid melengkapkan jadual sifat jirim (Mempunyai Jisim, Memenuhi Ruang, Isipadu Tetap, Bentuk Tetap) di dalam buku latihan."], "penutup": "Murid membincangkan mengapa gas boleh dimampatkan sedangkan pepejal tidak boleh dimampatkan.", "pentaksiran": "Laporan aktiviti eksperimen sifat jirim (KPS).", "bahanBantuBelajar": "Bikar, silinder penyukat, picagari, batu kecil, belon, Buku Teks m/s 180-183.", "refleksi": ""}, {"id": 62, "title": "Unit 8: Jirim", "minggu": 31, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Bahan", "topik": "Unit 8: Jirim", "standardKandungan": "8.1 Keadaan Jirim", "standardPembelajaran": "8.1.4 Mengitlak bahawa air boleh wujud dalam tiga keadaan jirim dengan menjalankan aktiviti.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat membuktikan bahawa air boleh wujud dalam keadaan pepejal (ais), cecair (air), dan gas (wap air) melalui aktiviti pemanasan ais dengan betul.", "kriteriaKejayaan": "(1) Murid boleh melabelkan tiga fasa fizikal air dengan betul. (2) Murid boleh menulis laporan ringkas perubahan keadaan fizikal ais semasa dipanaskan.", "setInduksi": "Guru mengeluarkan seketul ais dari peti sejuk mini makmal dan bertanyakan murid: \"Apakah keadaan jirim ais ini dan bagaimana ia boleh bertukar bentuk?\" (5 minit).", "penyampaian": ["Murid meneliti kisah \"Sang Ais dan Sang Kerikil\" berlumba lari (Buku Teks m/s 184-185).", "Murid menjalankan eksperimen Mari Uji: Tiga Keadaan Jirim Air (Buku Teks m/s 185) secara berkumpulan.", "Murid meletakkan ais dalam mangkuk pijar, mencatatkan keadaan pepejal awal.", "Murid memanaskan mangkuk pijar di atas penunu Bunsen selama 2 minit, mencatatkan ais melebur menjadi air (cecair).", "Murid meneruskan pemanasan sehingga air kering dan bertukar menjadi wap air (gas) (Buku Teks m/s 185).", "Murid melengkapkan jadual data laporan (Langkah 1, 3, dan 4)."], "penutup": "Murid membuat kesimpulan bahawa air adalah bahan unik yang mudah berubah fasa fizikal mengikut suhu.", "pentaksiran": "Pemerhatian amali eksperimen perubahan fasa air.", "bahanBantuBelajar": "Mangkuk pijar, penunu Bunsen, ais, jam randik, Buku Teks m/s 184-185.", "refleksi": ""}, {"id": 63, "title": "Unit 8: Jirim", "minggu": 32, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Bahan", "topik": "Unit 8: Jirim", "standardKandungan": "8.2 Perubahan Keadaan Jirim bagi Air", "standardPembelajaran": "8.2.1 Memerihalkan perubahan keadaan jirim bagi air dengan menjalankan aktiviti.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat menyenaraikan 5 proses perubahan keadaan jirim air (peleburan, pembekuan, penyejatan, pendidihan, kondensasi) beserta takrifan arah perubahan fasanya dengan betul.", "kriteriaKejayaan": "(1) Murid boleh mengaitkan peleburan dengan perubahan pepejal -> cecair. (2) Murid boleh mengaitkan kondensasi dengan perubahan gas -> cecair.", "setInduksi": "Guru menyembur cermin tingkap dengan nafas panas, meminta murid memerhatikan wap air yang terkumpul bertukar menjadi titisan cecair air (5 minit).", "penyampaian": ["Murid meneliti rajah Perubahan Keadaan Jirim Air (Buku Teks m/s 186-187).", "Guru menerangkan secara terperinci proses perubahan keadaan jirim air.", "Murid meneliti susunan zarah-zarah jirim: sangat rapat (pepejal), kurang rapat (cecair), menjauhi (gas) (Buku Teks m/s 186-187).", "Murid menyalin rajah kitaran perubahan fasa jirim air ke dalam buku latihan."], "penutup": "Murid melafazkan arah perubahan fasa secara kuiz pantas lisan.", "pentaksiran": "Lakaran rajah bersimbol perubahan keadaan jirim air.", "bahanBantuBelajar": "Kad rajah susunan zarah, Buku Teks m/s 186-187.", "refleksi": ""}, {"id": 64, "title": "Unit 8: Jirim", "minggu": 32, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Bahan", "topik": "Unit 8: Jirim", "standardKandungan": "8.2 Perubahan Keadaan Jirim bagi Air", "standardPembelajaran": "8.2.1 Memerihalkan perubahan keadaan jirim bagi air dengan menjalankan aktiviti.; 8.2.2 Menjelas dengan contoh perubahan keadaan jirim berlaku apabila jirim menerima atau kehilangan haba dengan menjalankan aktiviti.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat membezakan proses yang \"menerima haba\" dengan proses yang \"kehilangan haba\" melalui siri eksperimen ringkas pembekuan dan kondensasi dengan tepat.", "kriteriaKejayaan": "(1) Murid boleh membuktikan pembekuan air memerlukan kehilangan haba ke persekitaran (campuran ais & garam). (2) Murid boleh menerangkan proses kondensasi cermin mata berkabut (Buku Teks m/s 187).", "setInduksi": "Guru menunjukkan ketulan ais kering yang berasap, menjelaskan peranan penerimaan tenaga haba dari bilik (5 minit).", "penyampaian": ["Murid diterangkan konsep pemindahan haba: Jirim menerima haba (melebur, menyejat, mendidih) vs Jirim kehilangan haba (membeku, kondensasi) (Buku Teks m/s 186-187).", "Murid menjalankan eksperimen berkumpulan Mari Uji: Jirim Berubah Keadaan (Buku Teks m/s 188-190):", "Murid mencatatkan pemerhatian dan membina inferens saintifik ke dalam lembaran kerja."], "penutup": "Murid melancarkan simulasi fizikal Aktiviti Ria: Simulasi Susunan Zarah (Buku Teks m/s 191) menggunakan koordinasi gerakan fizikal murid di dalam petak 2m x 2m.", "pentaksiran": "Borang laporan amali eksperimen perubahan jirim air.", "bahanBantuBelajar": "Kotak polistirena, tabung uji, garam, pewarna, cermin, penunu Bunsen, Buku Teks m/s 188-191.", "refleksi": ""}, {"id": 65, "title": "Unit 8: Jirim", "minggu": 33, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Bahan", "topik": "Unit 8: Jirim", "standardKandungan": "8.2 Perubahan Keadaan Jirim bagi Air", "standardPembelajaran": "8.2.3 Menghubung kait perubahan keadaan jirim bagi air dengan pembentukan awan dan hujan.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat melukis kitaran air semula jadi dan menjelaskan proses penyejatan serta kondensasi yang terlibat dalam pembentukan awan dan hujan dengan betul.", "kriteriaKejayaan": "(1) Murid boleh menyatakan haba matahari menyebabkan air di bumi menyejat menjadi wap air. (2) Murid boleh mengaitkan pembentukan awan dengan proses kondensasi wap air di atmosfera yang sejuk.", "setInduksi": "Guru melukis gambar matahari, laut, dan awan di papan hitam, bertanyakan bagaimana air laut boleh naik ke langit menjadi awan (5 minit).", "penyampaian": ["Murid meneliti rajah Awan dan Hujan (Buku Teks m/s 192-193).", "Sesi sumbang saran peringkat kitaran air:", "Murid berbincang tentang kesan kepentingan kitaran air semula jadi kepada bekalan air tawar hidupan (Buku Teks m/s 193).", "Murid melukis kitaran air semula jadi yang lengkap di atas kertas lukisan dan melabelkan nama proses yang terlibat."], "penutup": "Murid membacakan puisi pendek kitaran air ciptaan sendiri secara berkumpulan.", "pentaksiran": "Hasil lukisan rajah Kitaran Air Semula Jadi murid.", "bahanBantuBelajar": "Kad rajah kitaran air, kertas lukisan, pensel warna, Buku Teks m/s 192-193.", "refleksi": ""}, {"id": 66, "title": "Unit 8: Jirim", "minggu": 33, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Bahan", "topik": "Unit 8: Jirim", "standardKandungan": "8.2 Perubahan Keadaan Jirim bagi Air", "standardPembelajaran": "8.2.3 Menghubung kait perubahan keadaan jirim bagi air dengan pembentukan awan dan hujan.; 8.2.4 Menjelaskan pemerhatian tentang perubahan keadaan jirim bagi air secara kreatif.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat membina satu model simulasi \"Hujan di dalam Besen\" dan membentangkan hasil pemerhatian proses perubahan fasa air secara kreatif.", "kriteriaKejayaan": "(1) Kumpulan boleh menerangkan peranan ais di atas plastik pembalut sebagai ejen penyejuk (kondensasi). (2) Murid boleh meramalkan akibat jika kitaran air di bumi terhenti.", "setInduksi": "Guru menunjukkan ketulan ais diletakkan di atas cawan plastik air panas, meminta murid memerhatikan pembentukan titisan air di bawah tapak cawan (5 minit).", "penyampaian": ["Murid menjalankan eksperimen Aktiviti Ria: Hujan dalam Besen Kaca (Buku Teks m/s 194) secara berkumpulan.", "Murid menyediakan radas: besen kaca, cawan jernih kecil, garam, air panas, plastik pembalut makanan, dan ketulan ais.", "Murid menuang air panas garam ke dalam besen (penyejatan), menutup besen dengan plastik, dan meletakkan ketulan ais di atas plastik (kondensasi) (Buku Teks m/s 194).", "Murid memerhatikan titisan air tawar menetes masuk ke dalam cawan jernih kecil selepas 10 minit.", "Setiap kumpulan membentangkan hasil penemuan dan menjelaskan hubung kait model dengan kitaran air sebenar."], "penutup": "Murid menjawab latihan pemahaman \"Asah Minda\" Buku Teks m/s 197-198 secara bertulis.", "pentaksiran": "Laporan eksperimen \"Hujan dalam Besen Kaca\" (KPS).", "bahanBantuBelajar": "Besen kaca, plastik pembalut, ketulan ais, air panas, garam, Buku Teks m/s 194.", "refleksi": ""}, {"id": 67, "title": "Unit 9: Fasa Bulan dan Buruj", "minggu": 34, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Bumi dan Angkasa", "topik": "Unit 9: Fasa Bulan dan Buruj", "standardKandungan": "9.1 Fasa Bulan", "standardPembelajaran": "9.1.1 Menyatakan Bulan tidak mengeluarkan cahaya tetapi memantulkan cahaya Matahari.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat menjelaskan bahawa Bulan tidak menghasilkan cahaya sendiri tetapi bersinar akibat memantulkan cahaya matahari berdasarkan model analogi dengan betul.", "kriteriaKejayaan": "(1) Murid boleh mengaitkan cermin bersinar dengan pantulan cahaya lampu suluh. (2) Murid boleh menulis kenyataan bertulis tentang sifat fizikal Bulan sebagai satelit semula jadi Bumi.", "setInduksi": "Guru menggelapkan makmal, menyalakan lampu suluh ke arah cermin muka, dan memantulkannya ke dinding. Guru bertanya: \"Adakah cermin ini mengeluarkan cahaya sendiri?\" (5 minit).", "penyampaian": ["Murid meneliti dialog Ana dan Melia tentang cahaya Bulan yang terang (Buku Teks m/s 200).", "Guru menerangkan konsep pantulan cahaya Matahari oleh Bulan menggunakan analogi cermin (cermin mewakili Bulan, lampu suluh mewakili Matahari) (Buku Teks m/s 200).", "Murid melukis rajah posisi Matahari, Bumi, dan Bulan yang menunjukkan laluan cahaya matahari dipantulkan ke permukaan Bumi.", "Murid menjawab soalan bertulis tentang mengapa Bulan kelihatan bersinar pada waktu malam."], "penutup": "Guru merumuskan bahawa Bulan hanyalah sebuah batuan sejuk yang bertindak sebagai pemantul cahaya matahari.", "pentaksiran": "Lembaran kerja lakaran aliran cahaya pantulan Bulan.", "bahanBantuBelajar": "Lampu suluh, cermin kecil, glob Bumi, Buku Teks m/s 200.", "refleksi": ""}, {"id": 68, "title": "Unit 9: Fasa Bulan dan Buruj", "minggu": 34, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Bumi dan Angkasa", "topik": "Unit 9: Fasa Bulan dan Buruj", "standardKandungan": "9.1 Fasa Bulan", "standardPembelajaran": "9.1.2 Memerihalkan Bulan berputar pada paksinya dan pada masa yang sama beredar mengelilingi Bumi dari aspek arah dan tempoh dengan menjalankan simulasi.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat menyatakan tempoh (27 1/3 hari) dan arah putaran & peredaran Bulan (lawan jam) serta menjelaskan mengapa permukaan Bulan yang sama sentiasa menghadap Bumi dengan tepat.", "kriteriaKejayaan": "(1) Murid boleh menyatakan tempoh putaran Bulan menyamai tempoh peredarannya mengelilingi Bumi. (2) Murid boleh melakonkan simulasi putaran dan peredaran Bulan secara berpasangan.", "setInduksi": "Guru mempamerkan glob Bumi dan sebiji bola tenis (Bulan). Guru memusingkan bola tenis mengelilingi glob tanpa memusingkan paksinya sendiri, bertanya murid apa yang janggal (5 minit).", "penyampaian": ["Murid mengkaji tempoh dan arah pergerakan Bulan (Buku Teks m/s 201-202):", "Murid melaksanakan Aktiviti Ria: Simulasi Putaran dan Peredaran Bulan (Buku Teks m/s 203) secara berkumpulan.", "Murid menggunakan belon bersaiz kecil yang ditampal kad mewakili muka Bulan, memegang belon, dan melakonkan pergerakan mengelilingi glob Bumi (pastikan muka belon sentiasa menghadap glob).", "Sesi soal jawab: \"Mengapa kita di Bumi tidak dapat melihat bahagian belakang Bulan?\"."], "penutup": "Murid menulis rumusan kronologi tempoh pergerakan Bulan di buku latihan.", "pentaksiran": "Pemerhatian amali simulasi pergerakan Bulan.", "bahanBantuBelajar": "Glob, belon, kad kecil, bola tenis, Buku Teks m/s 201-203.", "refleksi": ""}, {"id": 69, "title": "Unit 9: Fasa Bulan dan Buruj", "minggu": 35, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Bumi dan Angkasa", "topik": "Unit 9: Fasa Bulan dan Buruj", "standardKandungan": "9.1 Fasa Bulan", "standardPembelajaran": "9.1.3 Menggunakan perhubungan ruang dan masa untuk menggambarkan fasa Bulan dalam satu edaran lengkap mengikut takwim Qamari.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat menggambarkan 8 fasa Bulan dalam satu edaran lengkap mengikut urutan kronologi tarikh Takwim Qamari dengan betul.", "kriteriaKejayaan": "(1) Murid boleh melakar bentuk anak bulan, bulan sabit, separa, hampir purnama, dan purnama. (2) Murid boleh menyatakan tarikh Qamari bagi fasa bulan purnama (14, 15, 16 Qamari).", "setInduksi": "Guru memaparkan kalendar Hijrah (Takwim Qamari) dan bertanyakan bagaimana tarikh Hari Raya Aidilfitri ditentukan (5 minit).", "penyampaian": ["Murid meneroka rajah skematik Fasa Bulan (Buku Teks m/s 204-205).", "Guru menerangkan urutan fasa Bulan berdasarkan perubahan kedudukan Bulan mengelilingi Bumi: Anak Bulan $", "Murid menganalisis jadual tarikh Takwim Qamari (Buku Teks m/s 206).", "Murid melukis poster 8 fasa Bulan yang disusun melingkar mengikut kronologi tarikh Qamari di atas kertas lukisan."], "penutup": "Murid merumuskan bahawa takwim Qamari ditentukan sepenuhnya oleh kedudukan dan fasa fizikal Bulan.", "pentaksiran": "Poster kronologi 8 Fasa Bulan Takwim Qamari.", "bahanBantuBelajar": "Kalendar Hijrah, kertas lukisan, rajah fasa Bulan, Buku Teks m/s 204-206.", "refleksi": ""}, {"id": 70, "title": "Unit 9: Fasa Bulan dan Buruj", "minggu": 35, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Bumi dan Angkasa", "topik": "Unit 9: Fasa Bulan dan Buruj", "standardKandungan": "9.1 Fasa Bulan", "standardPembelajaran": "9.1.3 Menggunakan perhubungan ruang dan masa untuk menggambarkan fasa Bulan dalam satu edaran lengkap mengikut takwim Qamari.; 9.1.4 Menjelaskan pemerhatian tentang fasa bulan secara kreatif.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat menjalankan simulasi fasa Bulan menggunakan bebola polistirena dan melakarkan pemerhatian bentuk bulan sabit serta separa dengan tepat.", "kriteriaKejayaan": "(1) Murid boleh meniru kedudukan sudut (45°, 90°, 180°) untuk melihat bayang-bayang fasa Bulan dalam bilik gelap. (2) Murid boleh menerangkan mengapa anak bulan tidak kelihatan dari Bumi.", "setInduksi": "Guru menggelapkan makmal sepenuhnya dan menyalakan satu lampu terendak mentol terang di tengah bilik, menjelaskan peranan lampu sebagai Matahari (5 minit).", "penyampaian": ["Murid menjalankan eksperimen Mari Uji: Simulasi Fasa Bulan (Buku Teks m/s 206-207) secara berkumpulan di dalam makmal yang gelap.", "Murid menyediakan radas: bebola polistirena yang dicucuk pensel dan lampu terendak.", "Murid berdiri memegang bebola, menghadap lampu, dan melakukan putaran sudut badan (0° hingga 360°) mengikut langkah 2 hingga 7 (Buku Teks m/s 207).", "Murid memerhatikan fasa bulan sabit (sudut 45°), bulan separa (sudut 90°), dan bulan purnama (sudut 180°).", "Setiap murid melakarkan bentuk bayang-bayang bebola yang kelihatan pada setiap sudut di sehelai kertas."], "penutup": "Murid membincangkan soalan penaakulan: \"Mengapakah bulan kelihatan penuh ketika fasa bulan purnama?\" (Buku Teks m/s 207).", "pentaksiran": "Lakaran lembaran pemerhatian amali fasa Bulan.", "bahanBantuBelajar": "Bebola polistirena, pensel, lampu terendak, Buku Teks m/s 206-207.", "refleksi": ""}, {"id": 71, "title": "Unit 9: Fasa Bulan dan Buruj", "minggu": 36, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Bumi dan Angkasa", "topik": "Unit 9: Fasa Bulan dan Buruj", "standardKandungan": "9.2 Buruj", "standardPembelajaran": "9.2.1 Mengenal pasti buruj dan corak buruj.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat menamakan dan melakar corak 4 buruj utama (Biduk, Belantik, Pari, Skorpio) dengan betul serta menyatakan hemisfera penglihatannya.", "kriteriaKejayaan": "(1) Murid boleh mengaitkan buruj Biduk dengan corak senduk dan buruj Pari dengan corak layang-layang. (2) Murid boleh membezakan bentuk pemburu (Belantik) dengan kala jengking (Skorpio).", "setInduksi": "Guru menampal sekeping gambar bintang bertaburan di papan putih, meminta murid menyambung garisan titik untuk membentuk imej gayung (5 minit).", "penyampaian": ["Murid membaca pengenalan kegunaan buruj oleh pelayar zaman dahulu (Buku Teks m/s 208).", "Guru mendefinisikan Buruj: gugusan bintang yang kelihatan membentuk corak tertentu di langit pada waktu malam (Buku Teks m/s 208).", "Murid meneroka 4 buruj utama (Buku Teks m/s 209-210):", "Murid melukis 4 corak buruj tersebut di dalam buku latihan menggunakan pensel warna."], "penutup": "Murid membuat imbasan kod QR AR (Augmented Reality) DBP Sains Tahun 5 untuk melihat visual 3D buruj yang interaktif (Buku Teks m/s vi).", "pentaksiran": "Hasil lukisan dan pelabelan 4 buruj utama.", "bahanBantuBelajar": "Kad gambar buruj, aplikasi AR DBP Sains Tahun 5, Buku Teks m/s 208-210.", "refleksi": ""}, {"id": 72, "title": "Unit 9: Fasa Bulan dan Buruj", "minggu": 36, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Bumi dan Angkasa", "topik": "Unit 9: Fasa Bulan dan Buruj", "standardKandungan": "9.2 Buruj", "standardPembelajaran": "9.2.2 Menyatakan kegunaan buruj.; 9.2.3 Menjelaskan pemerhatian tentang buruj melalui lakaran, TMK, penulisan atau lisan secara kreatif.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat menyenaraikan 2 kegunaan utama buruj (petunjuk arah dan petunjuk musim) dan membina satu model buruj fizikal menggunakan plastisin dan lidi sate secara berkumpulan dengan betul.", "kriteriaKejayaan": "(1) Murid boleh menjelaskan buruj Biduk menunjuk ke utara dan buruj Pari ke selatan. (2) Murid boleh menerangkan peranan buruj Skorpio sebagai petunjuk musim menuai.", "setInduksi": "Guru membacakan kisah sekumpulan pengembara yang sesat di dalam hutan tebal pada waktu malam tanpa kompas, bertanyakan bagaimana mereka boleh keluar (5 minit).", "penyampaian": ["Murid mengkaji fungsi buruj (Buku Teks m/s 211-212):", "Murid melaksanakan Aktiviti Ria: Model Buruj (Buku Teks m/s 213) secara berkumpulan.", "Murid memotong lidi sate, membentukkan bebola plastisin kecil (bintang), dan menyambungkannya untuk menghasilkan model 3D buruj Biduk, Belantik, Pari, dan Skorpio.", "Setiap kumpulan membentangkan model buruj mereka dan menerangkan kegunaannya secara lisan."], "penutup": "Murid menjawab soalan bertulis \"Asah Minda\" Buku Teks m/s 215-216.", "pentaksiran": "Penilaian model 3D buruj berkumpulan dan keupayaan lisan menerangkan kegunaan.", "bahanBantuBelajar": "Lidi sate, gunting, plastisin, Buku Teks m/s 211-213.", "refleksi": ""}, {"id": 73, "title": "Unit 10: Mesin", "minggu": 37, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Teknologi dan Kehidupan Lestari", "topik": "Unit 10: Mesin", "standardKandungan": "10.1 Penggunaan Alat dalam Kehidupan", "standardPembelajaran": "10.1.1 Menyatakan kegunaan suatu alat yang terdapat di persekitaran murid.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat menyenaraikan sekurang-kurangnya 5 jenis peralatan persekitaran makmal/rumah beserta kegunaannya untuk memudahkan kerja manusia dengan betul.", "kriteriaKejayaan": "(1) Murid boleh menyatakan stapler digunakan untuk mencantumkan kertas. (2) Murid boleh mengaitkan roda pada kereta sorong dengan kemudahan pengangkutan beban.", "setInduksi": "Guru cuba mencantumkan 20 keping kertas menggunakan tangan kosong tanpa stapler atau klip, mencetuskan sumbang saran murid tentang kepentingan alat (5 minit).", "penyampaian": ["Murid membaca dialog persediaan buku skrap Tahun 5 Zamrud (Buku Teks m/s 218).", "Guru menerangkan definisi Mesin: alat atau perkakasan yang membantu memudahkan dan mempercepatkan kerja manusia (Buku Teks m/s 218).", "Murid menjalankan tinjauan ringkas makmal sains mengesan alat harian: stapler, pengetip kuku, gunting, pengasah pensel, kepala paip (Buku Teks m/s 219).", "Murid mencatat dan melengkapkan jadual \"Nama Alat dan Kegunaan\" di dalam buku nota."], "penutup": "Murid membincangkan bagaimana kehidupan manusia sebelum penemuan mesin-mesin ringkas.", "pentaksiran": "Jadual bertulis senarai kegunaan peralatan makmal.", "bahanBantuBelajar": "Stapler, pengetip kuku, gunting, pengasah pensel, Buku Teks m/s 218-219.", "refleksi": ""}, {"id": 74, "title": "Unit 10: Mesin", "minggu": 37, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Teknologi dan Kehidupan Lestari", "topik": "Unit 10: Mesin", "standardKandungan": "10.1 Penggunaan Alat dalam Kehidupan", "standardPembelajaran": "10.1.2 Menerangkan kombinasi fungsi mesin ringkas pada suatu alat yang membolehkan alat tersebut berfungsi melalui pemerhatian alat sebenar.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat mengenal pasti dan menerangkan kombinasi sekurang-kurangnya 2 jenis mesin ringkas pada pengasah pensel mekanikal, pengetip kuku, atau gergaji dahan dengan betul.", "kriteriaKejayaan": "(1) Murid boleh menyatakan pengetip kuku menggabungkan fungsi tuas (tekanan daya) dan baji (memotong kuku). (2) Murid boleh mengenal pasti takal, baji, dan skru pada gergaji dahan.", "setInduksi": "Guru membongkar sebuah pengasah pensel mekanikal dan mempamerkan bahagian gear dan bilah pisau (baji) di dalamnya (5 minit).", "penyampaian": ["Murid membaca huraian Kombinasi Fungsi Mesin Ringkas (Buku Teks m/s 220-221).", "Guru menerangkan interaksi komponen:", "Murid melaksanakan eksperimen Mari Uji: Saya Berguna dan Berfungsi (Buku Teks m/s 219) secara berkumpulan.", "Setiap kumpulan melakar salah satu alat tersebut, melabelkan bahagian mesin ringkas yang digabungkan, dan membentangkannya di depan kelas."], "penutup": "Murid merumuskan bahawa kecekapan sesuatu alat meningkat apabila terdapat kombinasi mesin ringkas yang harmoni.", "pentaksiran": "Lakaran berlabel kombinasi mesin ringkas pada peralatan fizikal.", "bahanBantuBelajar": "Jam tangan mekanikal, pengetip kuku, pengasah pensel mekanikal, Buku Teks m/s 219-221.", "refleksi": ""}, {"id": 75, "title": "Unit 10: Mesin", "minggu": 38, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Teknologi dan Kehidupan Lestari", "topik": "Unit 10: Mesin", "standardKandungan": "10.1 Penggunaan Alat dalam Kehidupan", "standardPembelajaran": "10.1.3高度 Menyatakan kepentingan kombinasi mesin ringkas untuk memastikan alat itu berfungsi dengan sempurna.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat menaakul kepentingan gabungan mesin ringkas pada gunting atau basikal dan menjelaskan akibat jika komponen tersebut tiada dengan betul.", "kriteriaKejayaan": "(1) Murid boleh menerangkan gunting tidak dapat berfungsi jika skru (pencantum) ditanggalkan. (2) Murid boleh menaakul peranan gear basikal dalam mengubah kelajuan kayuhan.", "setInduksi": "Guru memegang sebilah gunting yang telah ditanggalkan skru tengahnya, meminta murid cuba menggunting sehelai kertas. Sesi sumbang saran bermula (5 minit).", "penyampaian": ["Murid meneliti situasi 1 (basikal tiada rantai/gear) dan situasi 2 (gunting tiada skru) (Buku Teks m/s 222).", "Sesi perbincangan taakulan berkumpulan: Mengapa kombinasi mesin ringkas sangat penting bagi memastikan kelancaran pergerakan basikal?", "Murid melukis kartun situasi kegagalan alat akibat ketiadaan komponen mesin ringkas dan menulis dialog penerangan penaakulan di bawahnya.", "Setiap murid membentangkan hasil taakulan mereka kepada rakan sekumpulan."], "penutup": "Guru membuat rumusan bahawa reka bentuk mekanikal menghendaki integrasi yang kukuh antara semua bahagian.", "pentaksiran": "Catatan bertulis taakulan kesan kegagalan komponen alat.", "bahanBantuBelajar": "Gunting tanpa skru, gambar rajah basikal lengkap, Buku Teks m/s 222.", "refleksi": ""}, {"id": 76, "title": "Unit 10: Mesin", "minggu": 38, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Teknologi dan Kehidupan Lestari", "topik": "Unit 10: Mesin", "standardKandungan": "10.1 Penggunaan Alat dalam Kehidupan", "standardPembelajaran": "10.1.4 Menjana idea tentang kepentingan ciri penciptaan alat yang lestari.; 10.1.5 Menjelaskan pemerhatian tentang penggunaan alat dalam kehidupan secara kreatif.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat menyenaraikan 6 ciri penciptaan alat yang lestari dan membentangkan lakaran reka bentuk \"Tong Sampah Lestari\" secara berkumpulan dengan betul.", "kriteriaKejayaan": "(1) Murid boleh menamakan 6 ciri lestari (selamat, mesra alam, jangka hayat panjang, kos rendah, mudah diselenggara, bahan sesuai) (Buku Teks m/s 225). (2) Kumpulan boleh membentangkan rekaan tong sampah beroda yang ditransformasi kreatif.", "setInduksi": "Guru mempamerkan gambar pencakar sampah tradisional berbanding pencakar sampah mekanikal lestari, meminta murid membandingkan masa dan tenaga yang digunakan (5 minit).", "penyampaian": ["Murid meneliti perbincangan Ana dan ibunya tentang alat pemotong kentang dan reka bentuk tong sampah rumah yang berat (Buku Teks m/s 223-224).", "Guru menerangkan 6 ciri lestari di dalam rajah Ciri-ciri Penciptaan Alat yang Lestari (Buku Teks m/s 225).", "Murid melaksanakan Aktiviti Ria: Penciptaan Alat yang Lestari (Buku Teks m/s 226).", "Secara berkumpulan, murid merancang penambahbaikan tong sampah berat dengan menambah roda (roda & gandar), pedal pemijak penutup (tuas), dan partition pembahagi bahan kitar semula.", "Setiap kumpulan melakar reka bentuk lestari tersebut di atas kad manila dan membentangkannya di hadapan kelas."], "penutup": "Murid menjawab soalan pengukuhan \"Asah Minda\" Buku Teks m/s 229-230.", "pentaksiran": "Poster reka bentuk Tong Sampah Lestari berkumpulan (PBD).", "bahanBantuBelajar": "Kad manila, pen penanda, pensel warna, Buku Teks m/s 223-226.", "refleksi": ""}, {"id": 77, "title": "Pentaksiran Akhir Tahun (Kertas 1 - Objektif)", "minggu": 39, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Pentaksiran Holistik DSKP Sains Tahun 5", "topik": "Pentaksiran Akhir Tahun (Kertas 1 - Objektif)", "standardKandungan": "Penilaian Tahap Penguasaan Keseluruhan (Unit 1 hingga Unit 10)", "standardPembelajaran": "Ujian bertulis bertema merangkumi Kemahiran Saintifik, Sains Hayat, Sains Fizikal, Sains Bahan, Bumi dan Angkasa, serta Teknologi.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat menjawab sekurang-kurangnya 80% soalan objektif (Kertas 1) yang menguji pemahaman konsep-konsep asas sains Tahun 5 dengan betul.", "kriteriaKejayaan": "(1) Murid boleh membaca soalan dengan teliti dan memilih satu jawapan terbaik. (2) Murid menguruskan masa ujian (1 jam) dengan cekap.", "setInduksi": "Guru memberikan motivasi ringkas, membimbing murid melakukan regangan fizikal ringan, dan menerangkan peraturan serta adab menduduki pentaksiran bertulis (5 minit).", "penyampaian": ["Pengedaran kertas soalan Pentaksiran Akhir Tahun (Kertas 1 - 40 Soalan Objektif).", "Murid menduduki ujian secara senyap dan terkawal selama 1 jam.", "Guru mengawasi jalannya pentaksiran dan memastikan murid mematuhi masa yang ditetapkan.", "Kutipan kertas soalan setelah tamat masa peperiksaan."], "penutup": "Guru membimbing murid melakukan teknik bernafas lega dan mengucapkan tahniah atas usaha yang ditunjukkan.", "pentaksiran": "Pentaksiran Sumatif (Ujian Bertulis Kertas 1).", "bahanBantuBelajar": "Kertas soalan objektif, alat tulis.", "refleksi": ""}, {"id": 78, "title": "Pentaksiran Akhir Tahun (Kertas 2 - Subjektif)", "minggu": 39, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Pentaksiran Holistik DSKP Sains Tahun 5", "topik": "Pentaksiran Akhir Tahun (Kertas 2 - Subjektif)", "standardKandungan": "Penilaian Tahap Penguasaan Kemahiran Proses Sains (KPS)", "standardPembelajaran": "Penilaian bertulis KPS (PM, PB, PD, Hipotesis, DSO, Inferens) berdasarkan situasi eksperimen.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat melengkapkan jawapan bagi soalan struktur (Kertas 2) yang menguji kebolehan menganalisis data, membuat inferens, dan menulis kesimpulan saintifik dengan betul.", "kriteriaKejayaan": "(1) Murid boleh menulis pemboleh ubah dimanipulasikan dan bergerak balas berdasarkan jadual keputusan yang diberikan. (2) Murid boleh membina ayat kesimpulan saintifik yang lengkap.", "setInduksi": "Guru mengingatkan murid tentang kata kunci KPS (PM, PB, PD, hipotesis) melalui teknik visual ringkas di papan hitam (5 minit).", "penyampaian": ["Pengedaran kertas soalan Pentaksiran Akhir Tahun (Kertas 2 - Soalan Struktur KPS & KBAT).", "Murid menduduki ujian struktur secara individu dengan penuh fokus selama 1 jam.", "Guru melakukan pengawasan aktif bagi membimbing pengurusan masa murid.", "Kutipan skrip jawapan subjektif murid."], "penutup": "Guru mengucapkan syabas kepada seluruh kelas atas kesungguhan yang ditunjukkan sepanjang sesi pentaksiran akhir tahun.", "pentaksiran": "Pentaksiran Sumatif (Ujian Bertulis Kertas 2).", "bahanBantuBelajar": "Kertas soalan subjektif, alat tulis.", "refleksi": ""}, {"id": 79, "title": "Aplikasi Kemahiran Saintifik & PBD Refleksi", "minggu": 40, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Inkuiri dalam Sains", "topik": "Aplikasi Kemahiran Saintifik & PBD Refleksi", "standardKandungan": "1.1 Kemahiran Proses Sains (Pengukuhan)", "standardPembelajaran": "Aktiviti Pengukuhan Pembelajaran Inkuiri bersempena sambutan perayaan Deepavali (Pembuatan Kolam Rangoli Menggunakan Corak Geometri / Penggunaan Bahan Pewarna Semulajadi).", "objektifPembelajaran": "Di akhir pengajaran, murid dapat mengelaskan jenis bahan pewarna makanan semulajadi berdasarkan perasid / alkali serta melakar draf corak Rangoli yang bersimetri dengan betul.", "kriteriaKejayaan": "(1) Murid boleh menerangkan sifat asid/alkali bagi pewarna kunyit dan bunga telang menggunakan kertas litmus. (2) Murid boleh menyusun reka bentuk geometri kolam dengan kemas.", "setInduksi": "Guru memaparkan slaid gambar perayaan Deepavali dan reka bentuk seni \"Kolam Rangoli\" berwarna-warni, bertanya murid dari manakah warna tersebut diperoleh secara tradisional (5 minit).", "penyampaian": ["Murid diterangkan tentang perkaitan sains dalam kehidupan harian (tradisi pembuatan warna Kolam menggunakan beras dan pewarna asli).", "Murid menjalankan ujian ringkas menguji keasidan bahan pewarna asli (kunyit, bunga telang, perahan daun pandan) menggunakan kertas litmus merah dan biru.", "Murid merekodkan sifat kimia bahan pewarna tersebut ke dalam buku nota.", "Secara berpasangan, murid melakar draf seni hiasan Rangoli di atas kertas lukisan berasaskan corak geometri bersimetri (Aplikasi kemahiran ruang dan masa)."], "penutup": "Murid mempamerkan draf hiasan Rangoli di hadapan kelas untuk ulasan rakan.", "pentaksiran": "Pemerhatian amali pengujian keasidan pewarna semulajadi.", "bahanBantuBelajar": "Kertas litmus, ekstrak kunyit, bunga telang, daun pandan, Buku Teks m/s 16 (soalan pengukuhan sifat kimia).", "refleksi": ""}, {"id": 80, "title": "Unit 10: Mesin (Aktiviti Rekacipta)", "minggu": 40, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Teknologi dan Kehidupan Lestari", "topik": "Unit 10: Mesin (Aktiviti Rekacipta)", "standardKandungan": "10.1 Penggunaan Alat dalam Kehidupan (Aktiviti Pengayaan)", "standardPembelajaran": "Projek Kreatif Reka Cipta Alat Bersempena Cuti Deepavali.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat mencadangkan satu reka bentuk alat pembungkus hadiah yang menerapkan kombinasi sekurang-kurangnya 2 jenis mesin ringkas secara kreatif.", "kriteriaKejayaan": "(1) Murid boleh membina draf rekaan menggunakan lakaran berlabel fungsi komponen lestari. (2) Murid boleh menaakul kebolehlaksanaan alat rekaan tersebut secara lisan.", "setInduksi": "Guru menunjukkan kotak hadiah Deepavali yang dibungkus tidak kemas, menggalakkan murid menjana idea alat yang boleh mempercepat pembungkusan (5 minit).", "penyampaian": ["Murid merujuk projek pengayaan Santai Sains: Bekas Pita Pelekat (Buku Teks m/s 227-228).", "Murid meneliti langkah pembinaan menggunakan kadbod, batang aiskrim, lidi sate, baji (pisau pengasah pensel), dan roda & gandar.", "Secara berkumpulan, murid menyediakan draf pelan tindakan, menyenaraikan bahan kitar semula yang diperlukan untuk dibawa pada minggu berikutnya, dan memotong kadbod mengikut saiz bulatan pita (Buku Teks m/s 227).", "Setiap kumpulan menerangkan bagaimana baji pada pisau pengasah membantu memotong pita pelekat dengan selamat (Buku Teks m/s 228)."], "penutup": "Murid mengemaskan kawasan makmal dan menyimpan bahan draf projek dengan teratur di dalam loker kumpulan.", "pentaksiran": "Penilaian draf rekacipta bekas pita pelekat lestari.", "bahanBantuBelajar": "Kadbod, pita pelekat, Buku Teks m/s 227-228.", "refleksi": ""}, {"id": 81, "title": "Aplikasi Teknologi Rekacipta (STEM)", "minggu": 41, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Inkuiri dalam Sains", "topik": "Aplikasi Teknologi Rekacipta (STEM)", "standardKandungan": "10.1 Penggunaan Alat dalam Kehidupan (Amali STEM)", "standardPembelajaran": "Projek Fizikal Reka Cipta Alat Lestari.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat membina fizikal \"Bekas Pita Pelekat\" menggunakan bahan kitar semula berdasarkan draf reka bentuk dengan kemas dan selamat.", "kriteriaKejayaan": "(1) Murid boleh memotong kadbod mengikut saiz C, D, E, F, G, dan H dengan ketebalan yang konsisten (Buku Teks m/s 228). (2) Murid boleh melekatkan baji pengasah pensel pada hujung kadbod dengan selamat.", "setInduksi": "Guru mengimbas kembali langkah pemotongan kadbod yang dibincangkan pada kelas lepas dan membentangkan standard keselamatan penggunaan pisau (5 minit).", "penyampaian": ["Murid bekerjasama dalam kumpulan membina model fizikal Bekas Pita Pelekat (Buku Teks m/s 227-228).", "Murid menggunakan pisau kecil, pembaris, kadbod, batang aiskrim, lidi sate, dan pistol perekat panas untuk memasang bahagian model (a hingga b) (Buku Teks m/s 227).", "Murid menanggalkan baji pengasah pensel menggunakan pemutar skru dan melekatkannya pada kedudukan pemotong (Buku Teks m/s 228).", "Murid memasang pita pelekat ke dalam model, menguji fungsi pemotongan baji, dan mencatatkan tahap kecekapan pemotongan."], "penutup": "Murid menghias bekas pita pelekat mereka menggunakan bahan terbuang hiasan.", "pentaksiran": "Penilaian produk fizikal Bekas Pita Pelekat Lestari (PBD STEM).", "bahanBantuBelajar": "Kadbod, pisau kecil, pemutar skru, pistol perekat panas, pengasah pensel lama, Buku Teks m/s 227-228.", "refleksi": ""}, {"id": 82, "title": "Unit 9: Fasa Bulan dan Buruj (Aktiviti Kreatif)", "minggu": 41, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Bumi dan Angkasa", "topik": "Unit 9: Fasa Bulan dan Buruj (Aktiviti Kreatif)", "standardKandungan": "9.1 Fasa Bulan (Aktiviti Pengayaan)", "standardPembelajaran": "Rekonstruksi visual fasa Bulan secara interaktif menggunakan cawan plastik jernih.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat membina satu alat \"Cawan Fasa Bulan\" yang boleh diputar menunjukkan 8 transisi fasa Bulan dengan betul secara individu.", "kriteriaKejayaan": "(1) Murid boleh melakar 8 fasa Bulan mengikut urutan pada bahagian luar cawan kedua dengan kemas. (2) Murid boleh menerangkan perubahan fasa Bulan semasa cawan diputar.", "setInduksi": "Guru menunjukkan dua cawan jernih bertindan yang boleh diputar menghasilkan kesan animasi fasa Bulan, menarik minat murid (5 minit).", "penyampaian": ["Murid merujuk kepada panduan Santai Sains: Cawan Fasa Bulan (Buku Teks m/s 214).", "Setiap murid dibekalkan 2 cawan plastik jernih, kertas hitam, kertas kuning, gam, dan pen penanda jernih.", "Murid mengikut langkah 1 hingga 6 (Buku Teks m/s 214): memotong kertas kuning berbentuk bulatan Bulan, menampalnya di cawan pertama, menyarungkan cawan kedua, dan melakar fasa Bulan pada cawan luar.", "Murid memutarkan cawan kedua secara individu untuk menyemak ketepatan animasi fasa Bulan."], "penutup": "Murid menceritakan perubahan fasa Bulan berdasarkan kedudukan sudut peredaran Bulan menggunakan model cawan mereka kepada rakan sebelah.", "pentaksiran": "Penghasilan model Cawan Fasa Bulan secara kreatif.", "bahanBantuBelajar": "Dua cawan jernih, kertas hitam & kuning, pen penanda, Buku Teks m/s 214.", "refleksi": ""}, {"id": 83, "title": "Unit 8: Jirim (Aktiviti Santai Sains)", "minggu": 42, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Bahan", "topik": "Unit 8: Jirim (Aktiviti Santai Sains)", "standardKandungan": "8.2 Perubahan Keadaan Jirim bagi Air", "standardPembelajaran": "Penghasilan produk kristal melalui proses penyejatan air.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat membina set \"Lidi Hablur\" menggunakan larutan gula tepu untuk menunjukkan proses penyejatan menghasilkan kristal dengan betul secara berkumpulan.", "kriteriaKejayaan": "(1) Murid boleh menyediakan larutan gula tepu (300 g gula + 150 ml air panas) dengan betul. (2) Murid boleh menerangkan peranan penyejatan air dalam pembentukan hablur gula di sekeliling lidi.", "setInduksi": "Guru menunjukkan sebutir batu kristal permata asli dan bertanya: \"Bagaimanakah kita boleh membina gula-gula kristal yang manis di dalam makmal?\" (5 minit).", "penyampaian": ["Murid merujuk kepada panduan Santai Sains: Lidi Hablur (Buku Teks m/s 195).", "Guru menerangkan perkaitan proses penyejatan cecair yang meninggalkan zarah pepejal membentuk kristal (hablur).", "Murid bekerja dalam kumpulan (menggunakan pemanas atau air panas yang disediakan guru): melarutkan 300 g gula ke dalam 150 ml air panas, mengaduk rata, menuang ke dalam cawan plastik, dan menambah pewarna makanan (Buku Teks m/s 195).", "Murid menyepit lidi sate menggunakan penyepit baju dan merendamkannya di dalam larutan gula tersebut.", "Murid meletakkan cawan-cawan tersebut di sudut belakang makmal untuk dibiarkan tersejat secara perlahan selama 5 hari."], "penutup": "Murid mengemaskan kawasan kerja dan mencuci radas dapur dengan bersih.", "pentaksiran": "Pemerhatian penyediaan larutan kristal jirim.", "bahanBantuBelajar": "Gula (300 g), air panas, lidi sate, penyepit baju, cawan plastik, Buku Teks m/s 195.", "refleksi": ""}, {"id": 84, "title": "Unit 6: Haba (Aktiviti Amali Santai)", "minggu": 42, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Sains Fizikal", "topik": "Unit 6: Haba (Aktiviti Amali Santai)", "standardKandungan": "6.1 Haba dan Suhu (Aktiviti Pengayaan)", "standardPembelajaran": "Rekonstruksi peranti penyukat suhu secara kreatif.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat membina satu model \"Termometer Buatan Sendiri\" menggunakan botol plastik dan air berwarna untuk menunjukkan pengembangan gas/cecair apabila menerima haba dengan betul.", "kriteriaKejayaan": "(1) Murid boleh menerangkan mengapa aras air berwarna dalam penyedut minuman naik apabila botol direndam air panas. (2) Murid boleh menjelaskan mengapa aras menurun apabila botol direndam di dalam air batu (kehilangan haba).", "setInduksi": "Guru mencelupkan termometer makmal ke dalam air panas secara dramatik, murid memerhatikan kenaikan aras merkuri dan membincangkan prinsipnya (5 minit).", "penyampaian": ["Murid merujuk panduan Santai Sains: Termometer Saya (Buku Teks m/s 160).", "Setiap kumpulan menyediakan botol plastik yang diisi air berwarna, menyarungkan belon pada muncung botol, mengikatnya dengan gelang getah, dan menebuk lubang kecil untuk memasukkan penyedut minuman jernih (Buku Teks m/s 160).", "Murid merendam botol plastik ke dalam besen air panas (aras air berwarna naik) dan mencatatkan pemerhatian.", "Murid memindahkan botol ke dalam besen air ais (aras air berwarna turun) dan mencatatkan pemerhatian (Buku Teks m/s 160).", "Setiap kumpulan membentangkan hubungan sebab-akibat pengembangan cecair akibat pemindahan tenaga haba."], "penutup": "Murid mencuci botol dan mengeringkan meja makmal dengan kemas.", "pentaksiran": "Laporan pemerhatian pergerakan cecair termometer.", "bahanBantuBelajar": "Botol plastik, air berwarna, penyedut minuman, belon, gelang getah, ais, air panas, Buku Teks m/s 160.", "refleksi": ""}, {"id": 85, "title": "Aktiviti Pengurusan Makmal & Stor Sains", "minggu": 43, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Inkuiri dalam Sains", "topik": "Aktiviti Pengurusan Makmal & Stor Sains", "standardKandungan": "Pengurusan Bilik Sains, Pembersihan Peralatan Makmal, dan Inventori Radas Sains", "standardPembelajaran": "Amalan Kebersihan, Penyimpanan Alatan, dan Penyelenggaraan Radas Sains secara sistematik sebelum cuti sekolah bermula.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat membersihkan bikar, silinder penyukat, termometer, dan menyusunnya ke dalam kabinet makmal mengikut kategori bahan dengan selamat dan kemas.", "kriteriaKejayaan": "(1) Murid boleh membersihkan peralatan makmal tanpa memecahkan sebarang radas kaca. (2) Murid boleh mengelaskan alatan kaca, plastik, dan logam ke dalam rak inventori yang betul.", "setInduksi": "Guru menunjukkan gambar Bilik Sains yang kemas, tersusun, dan bebas dari debu, bertanyakan murid adakah makmal sekolah sedia untuk ditinggalkan sepanjang cuti panjang akhir tahun (5 minit).", "penyampaian": ["Guru memberikan taklimat pembahagian tugas gotong-royong akhir tahun mengikut zon (Zon Alatan Kaca, Zon Alatan Plastik, Zon Bahan STEM, Zon Kebersihan Meja).", "Murid mengikut kumpulan masing-masing mula mengumpul radas makmal yang telah digunakan sepanjang tahun.", "Murid membersihkan bikar, kelalang kon, silinder penyukat menggunakan sabun pencuci makmal dan mengeringkannya menggunakan kain bersih.", "Murid menyusun termometer ke dalam bekas asalnya secara menegak untuk mengelakkan kerosakan merkuri.", "Setiap kumpulan melaporkan status stok alatan kepada guru makmal menggunakan senarai semak inventori ringkas."], "penutup": "Murid memastikan semua suis elektrik makmal dimatikan dan pintu loker dikunci rapat.", "pentaksiran": "Pemerhatian amalan gotong-royong makmal dan disiplin murid.", "bahanBantuBelajar": "Sabun pencuci radas, kain lap kering, borang inventori makmal, senarai semak.", "refleksi": ""}, {"id": 86, "title": "Aktiviti Refleksi Pencapaian & Apresiasi Sains", "minggu": 43, "hari": "", "tarikh": "", "kelas": "", "masa": "", "mataPelajaran": "Sains", "tema": "Inkuiri dalam Sains", "topik": "Aktiviti Refleksi Pencapaian & Apresiasi Sains", "standardKandungan": "Refleksi Kendiri Murid dan Penilaian Portfolio PBD Sains Tahun 5 SK 2026", "standardPembelajaran": "Perkongsian hasil refleksi kendiri murid, penyerahan sijil kecemerlangan PBD, dan majlis apresiasi pencapaian STEM murid sepanjang tahun.", "objektifPembelajaran": "Di akhir pengajaran, murid dapat menulis sekurang-kurangnya 3 perkara penting atau kemahiran saintifik yang paling digemari sepanjang tahun dan membentangkannya secara lisan.", "kriteriaKejayaan": "(1) Murid boleh berkongsi refleksi pencapaian sains hayat, sains fizikal, atau sains bahan kegemaran masing-masing. (2) Murid boleh memberikan ucapan penghargaan kepada rakan sekumpulan.", "setInduksi": "Guru memainkan montase video/foto aktiviti eksperimen murid sepanjang tahun 2026 di dalam Bilik Sains untuk mencetuskan suasana gembira dan haru (5 minit).", "penyampaian": ["Murid diberi sekeping kad refleksi bertajuk \"Sains & Saya: Detik Indah 2026\".", "Setiap murid menulis secara individu pencapaian kemahiran proses sains terbaik yang telah dikuasai (contoh: mengeksperimen, membuat hipotesis).", "Sesi perkongsian mikrofon terbuka: Murid tampil ke hadapan berkongsi pengalaman manis membina kapal terbang kertas, mencampur gliserin buih gergasi, atau melakar laluan darah.", "Guru mengedarkan anugerah bertulis \"Apresiasi STEM Muda 2026\" kepada murid yang menunjukkan usaha berterusan.", "Murid membersihkan bilik darjah dan mengumpulkan kad refleksi di meja guru untuk disimpan dalam fail peribadi."], "penutup": "Sesi bersalaman dan ucapan terima kasih daripada murid kepada guru makmal sains.", "pentaksiran": "Penilaian portfolio refleksi kendiri murid.", "bahanBantuBelajar": "Kad refleksi, tayangan slaid montase gambar, sijil apresiasi STEM.", "refleksi": ""}]};